1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.ArrayList;
6	import java.util.List;
7	import java.util.Map;
8	import java.util.stream.Collectors;
9	import net.officefloor.hq.app.access.AccessService;
10	import net.officefloor.hq.app.access.Permission;
11	import net.officefloor.hq.app.access.Role;
12	import net.officefloor.hq.app.holiday.HolidayService;
13	import net.officefloor.hq.app.period.Period;
14	import net.officefloor.hq.app.period.PeriodService;
15	import net.officefloor.hq.app.person.PersonRepository;
16	import net.officefloor.hq.app.person.WatchService;
17	import net.officefloor.hq.app.sheet.DatedSettings;
18	import net.officefloor.hq.app.sheet.SheetRepository;
19	import net.officefloor.hq.app.sheet.SheetService;
20	import net.officefloor.hq.app.person.Person;
21	import net.officefloor.hq.app.rate.RateService;
22	import net.officefloor.hq.app.rate.RateTable;
23	import net.officefloor.hq.app.rollup.Rollup;
24	import net.officefloor.hq.app.sheet.TodayChanged;
25	import org.springframework.context.ApplicationEventPublisher;
26	import org.springframework.context.event.EventListener;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.stereotype.Service;
29	import org.springframework.transaction.annotation.Transactional;
30	import org.springframework.web.server.ResponseStatusException;
31	
32	/**
33	 * The claims on a sheet: listed per person newest first, added, edited and moved through their
34	 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
35	 * its number, which is never reused. A claim is numbered when it is settled or approved (an OPEN, PENDING or
36	 * REVIEW claim has no number; one numbered on opening before keeps it); a claim settled while period numbering
37	 * is on is numbered within its period instead of sheet-wide. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
38	 * (at least the sheet's floor then), or at the
39	 * figure a statement bound it to, plus the late charge it has then. A claim belongs to the period containing its due-by
40	 * (fixed when it was added, moved past the sheet's holidays then); no claim due by a date inside a closed period can be added, edited or moved,
41	 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
42	 * settling a claim whose due is above the sheet's clerk limit leaves it PENDING instead; a steward settles
43	 * anything, and approves a PENDING claim (settling it, its due fixed then) or rejects it with a reason
44	 * (back to OPEN), as may the user named as the person's approver; neither the user who opened a claim nor the one who last edited it can settle or approve it. A steward re-settles a SETTLED claim,
45	 * fixing its due again at the figure it would have today as an OPEN claim bound by no statement. A claim
46	 * with a negative amount is a correction: it is added or edited only when it names, by number, a SETTLED
47	 * claim of the same person, and only a correction names one. A claim whose due is above the sheet's proof
48	 * threshold in force on its date cannot be settled or approved while it has no proof. A claim whose due is above
49	 * the sheet's review threshold in force on its date goes to REVIEW when opened, unnumbered, until a steward
50	 * reviews it (OPEN).
51	 */
52	@Service
53	public class ClaimService {
54	
55	    private final ClaimRepository claims;
56	    private final PersonRepository people;
57	    private final SheetService sheets;
58	    private final SheetRepository sheetRows;
59	    private final RateService rates;
60	    private final Rollup rollup;
61	    private final PeriodService periods;
62	    private final AccessService access;
63	    private final WatchService watches;
64	    private final HolidayService holidays;
65	    private final Tags tags;
66	    private final VoidReasons voidReasons;
67	    private final ApplicationEventPublisher events;
68	
69	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
70	            SheetRepository sheetRows, RateService rates, Rollup rollup, PeriodService periods, AccessService access,
71	            WatchService watches, HolidayService holidays, Tags tags, VoidReasons voidReasons,
72	            ApplicationEventPublisher events) {
73	        this.tags = tags;
74	        this.voidReasons = voidReasons;
75	        this.holidays = holidays;
76	        this.access = access;
77	        this.watches = watches;
78	        this.rollup = rollup;
79	        this.periods = periods;
80	        this.claims = claims;
81	        this.people = people;
82	        this.sheets = sheets;
83	        this.sheetRows = sheetRows;
84	        this.rates = rates;
85	        this.events = events;
86	    }
87	
88	    /** Every claim on the sheet by the person who made it, each person's newest first. */
89	    @Transactional(readOnly = true)
90	    public Map<Long, List<Claim>> bySheet(String sheetId) {
91	        return claims.findBySheetIdOrderByListedDesc(sheetId).stream()
92	                .collect(Collectors.groupingBy(Claim::getPersonId));
93	    }
94	
95	    @Transactional(readOnly = true)
96	    public List<Claim> forPerson(String sheetId, long personId) {
97	        return claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, personId);
98	    }
99	
100	    /** Add a claim; a date left out takes the sheet's entry date while set, else its today. Returns the person it belongs to. */
101	    @Transactional
102	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
103	        return add(sheetId, user, personId, amount, date, note, null);
104	    }
105	
106	    /**
107	     * Add a claim, a correction naming the number of the claim it corrects; a date left out takes the
108	     * sheet's entry date while set, else its today. Returns the person it belongs to.
109	     */
110	    @Transactional
111	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
112	            String corrects) {
113	        return add(sheetId, user, personId, amount, date, note, corrects, null);
114	    }
115	
116	    /**
117	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String)} does, carrying an
118	     * external reference (surrounding spaces removed; blank: none), refused when a claim on the sheet already
119	     * carries it, compared without regard to case. Returns the person it belongs to.
120	     */
121	    @Transactional
122	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
123	            String corrects, String ref) {
124	        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
125	    }
126	
127	    /**
128	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String)} does,
129	     * carrying the tags in the comma separated text (see {@link Tags#normalize}; null: none). Returns the
130	     * person it belongs to.
131	     */
132	    @Transactional
133	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
134	            String corrects, String ref, String tagText) {
135	        return addClaim(sheetId, user, personId, amount, date, note, corrects, ref, tagText).getPersonId();
136	    }
137	
138	    /**
139	     * Add a claim as {@link #add(String, String, long, BigDecimal, LocalDate, String, String, String, String)} does; returns the claim.
140	     * Its due-by is fixed by the terms in force on the day it is created (the sheet's today), not on its date: the
141	     * person's own terms, the terms of the grade they have that day and the sheet's are each looked up on that day.
142	     */
143	    @Transactional
144	    public Claim addClaim(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
145	            String corrects, String ref, String tagText) {
146	        String tagged = Tags.normalize(tagText);
147	        String reference = requireFreeRef(sheetId, ref, null);
148	        Person person = people.findByIdAndSheetId(personId, sheetId)
149	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
150	        LocalDate on = date != null ? date : sheets.claimDate(sheetId);
151	        sheets.load(sheetId, user);
152	        LocalDate created = sheets.today(sheetId);
153	        int terms = sheets.settings(sheetId).termsFor(person.termsOn(created), person.gradeOn(created), created);
154	        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
155	        periods.requireOpen(sheetId, dueBy);
156	        requireNotRetired(person, on);
157	        LocalDate correctsDate = requireCorrects(sheetId, personId, amount, corrects, null);
158	        Rollup.Figures before = rollup.figures(sheetId);
159	        Claim claim = new Claim(sheetId, personId, amount, on, note == null ? "" : note, corrects);
160	        claim.setCorrectsDate(correctsDate);
161	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy).isPresent());
162	        claim.setDueBy(dueBy);
163	        claim.setTerms(terms);
164	        claim.setRef(reference);
165	        claim.setTags(tagged);
166	        log(sheetId, user, claim, person);
167	        claims.saveAndFlush(claim);
168	        tags.use(sheetId, tagged);
169	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null,
170	                null, null, reference, tagged.isEmpty() ? null : tagged));
171	        if (claim.isLateEntry()) {
172	            events.publishEvent(new ClaimChanged("LATE_ENTRY", sheetId, user, person.getName(), amount, on, null, null));
173	        }
174	        rollup.changed(sheetId, user, before);
175	        return claim;
176	    }
177	
178	    /**
179	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
180	     * added again instead), and an edit is refused when a closed period contains its due-by (which an edit
181	     * leaves as it was fixed), or
182	     * when the date it is left with is after its person's retirement date, or when its external reference
183	     * (surrounding spaces removed; blank: none) is carried by another claim on the sheet, compared without
184	     * regard to case, or when the claim has lines and the amount is another than theirs added up. Its tags are
185	     * those in the comma separated text (see {@link Tags#normalize}; null: none).
186	     * Returns the person it belongs to.
187	     */
188	    @Transactional
189	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
190	            String corrects, String ref, String tagText) {
191	        String tagged = Tags.normalize(tagText);
192	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
193	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
194	        String reference = requireFreeRef(sheetId, ref, claimId);
195	        LocalDate on = date != null ? date : sheets.today(sheetId);
196	        periods.requireOpen(sheetId, claim.getDueBy());
197	        if (claim.getStatus() != ClaimStatus.DRAFT) {
198	            throw new ResponseStatusException(HttpStatus.CONFLICT,
199	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
200	        }
201	        requireNotLockedByOther(claim, user);
202	        if (claim.hasLines() && amount.compareTo(claim.getAmount()) != 0) {
203	            throw new ResponseStatusException(HttpStatus.CONFLICT,
204	                    "The claim's amount is its lines added up (" + claim.getAmount().toPlainString() + ")");
205	        }
206	        people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
207	        LocalDate correctsDate = requireCorrects(sheetId, claim.getPersonId(), amount, corrects, claimId);
208	        Rollup.Figures before = rollup.figures(sheetId);
209	        claim.setAmount(amount);
210	        claim.setCorrects(corrects);
211	        claim.setCorrectsDate(correctsDate);
212	        claim.setDate(on);
213	        claim.setNote(note == null ? "" : note);
214	        claim.setRef(reference);
215	        claim.setTags(tagged);
216	        claim.setLockedBy(null);
217	        claim.setEditedBy(user);
218	        claims.flush();
219	        tags.use(sheetId, tagged);
220	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
221	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
222	                claim.getDate(), claim.getShownNumber(), null));
223	        rollup.changed(sheetId, user, before);
224	        return claim.getPersonId();
225	    }
226	
227	    /**
228	     * Change a claim's amount alone, keeping its date, note and the claim it corrects; refused exactly as
229	     * an {@link #edit} with that amount is. Returns the person it belongs to.
230	     */
231	    @Transactional
232	    public long editAmount(String sheetId, String user, long claimId, BigDecimal amount) {
233	        Claim claim = claim(sheetId, claimId);
234	        return edit(sheetId, user, claimId, amount, claim.getDate(), claim.getNote(), claim.getCorrects(),
235	                claim.getRef(), claim.getTags());
236	    }
237	
238	    /**
239	     * An external reference with its surrounding spaces removed, or null when blank; refused when a claim on
240	     * the sheet other than {@code claimId} (null: any claim) carries it, compared without regard to case.
241	     */
242	    String requireFreeRef(String sheetId, String ref, Long claimId) {
243	        String reference = ref == null || ref.isBlank() ? null : ref.strip();
244	        if (reference != null && (claimId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, reference)
245	                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, reference, claimId))) {
246	            throw new ResponseStatusException(HttpStatus.CONFLICT,
247	                    "The reference \"" + reference + "\" is already used on the sheet");
248	        }
249	        return reference;
250	    }
251	
252	    /**
253	     * Open a claim's editor, locking the claim for every other user until the editor is saved or cancelled
254	     * or the sheet's today changes. Only a DRAFT due by a date outside every closed period can be edited, and a claim
255	     * another user's editor holds is refused; a refusal takes no lock. No audit line. Returns the person
256	     * it belongs to.
257	     */
258	    @Transactional
259	    public long lock(String sheetId, String user, long claimId) {
260	        Claim claim = claim(sheetId, claimId);
261	        if (claim.getStatus() != ClaimStatus.DRAFT) {
262	            throw new ResponseStatusException(HttpStatus.CONFLICT,
263	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
264	        }
265	        requireNotLockedByOther(claim, user);
266	        claim.setLockedBy(user);
267	        claims.flush();
268	        return claim.getPersonId();
269	    }
270	
271	    /** Cancel a claim's editor, releasing the user's lock on it; another user's lock stays. Returns the person. */
272	    @Transactional
273	    public long unlock(String sheetId, String user, long claimId) {
274	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
275	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
276	        if (user.equals(claim.getLockedBy())) {
277	            claim.setLockedBy(null);
278	            claims.flush();
279	        }
280	        return claim.getPersonId();
281	    }
282	
283	    /** A change of the sheet's today releases every editor's lock on its claims. */
284	    @EventListener
285	    @Transactional
286	    public void on(TodayChanged e) {
287	        claims.findBySheetIdAndLockedByIsNotNull(e.sheetId()).forEach(c -> c.setLockedBy(null));
288	        claims.flush();
289	    }
290	
291	    private static void requireNotLockedByOther(Claim claim, String user) {
292	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
293	            throw new ResponseStatusException(HttpStatus.CONFLICT,
294	                    "The claim is being edited by " + claim.getLockedBy());
295	        }
296	    }
297	
298	    /**
299	     * Move a claim to a status; a move its status does not allow, opening, settling or voiding by a role the
300	     * sheet's permission matrix does not allow, settling by the user who opened
301	     * the claim, or moving a claim due by a date inside a closed period, is refused and changes nothing. Settling
302	     * by a clerk a claim whose due is above the clerk limit leaves it PENDING.
303	     * Returns the person it belongs to.
304	     */
305	    @Transactional
306	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
307	        return move(sheetId, user, claimId, next, null);
308	    }
309	
310	    /**
311	     * Number a bulk settle that settled the claims (to SETTLED or PENDING) as the sheet's next settle batch,
312	     * each claim showing it, and record it with the frozen figures of those SETTLED added up. Returns the
313	     * batch number.
314	     */
315	    @Transactional
316	    public int settleBatch(String sheetId, String user, List<Long> claimIds) {
317	        int batch = sheets.nextSettleBatch(sheetId);
318	        BigDecimal total = BigDecimal.ZERO;
319	        for (long id : claimIds) {
320	            Claim claim = claim(sheetId, id);
321	            claim.setSettleBatch(batch);
322	            if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
323	                total = total.add(claim.getSettledDue());
324	            }
325	        }
326	        claims.flush();
327	        events.publishEvent(new BatchSettled(sheetId, user, batch, claimIds.size(), total));
328	        return batch;
329	    }
330	
331	    /** The number of the sheet's last settle batch; 0 when there has been none. */
332	    public int lastSettleBatch(String sheetId) {
333	        return sheets.lastSettleBatch(sheetId);
334	    }
335	
336	    /**
337	     * Move a claim to a status as {@link #move(String, String, long, ClaimStatus)}; a claim is voided with the
338	     * given reason, which while the sheet's list of void reasons is not empty must be on it, else the void is
339	     * refused (see {@link VoidReasons#require}).
340	     */
341	    @Transactional
342	    public long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
343	        return move(sheetId, user, claimId, next, voidReason, true);
344	    }
345	
346	    /**
347	     * Move a claim as {@link #move(String, String, long, ClaimStatus, String)}; without the four-eyes and
348	     * proof checks when they were judged on another claim (a part-settle judges them on the claim split).
349	     */
350	    private long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
351	            boolean judgeHere) {
352	        return move(sheetId, user, claimId, next, voidReason, judgeHere, null);
353	    }
354	
355	    /** A claim's due as it stood at the end of a past day of the sheet (null: n/a), to settle it at. */
356	    public record DueThen(LocalDate on, BigDecimal due) {
357	    }
358	
359	    /**
360	     * The claim's due as the sheet shows it now, as of the date given; empty when the sheet has no such
361	     * claim. Read within {@link net.officefloor.hq.app.asof.SheetPasts#asOf}, it is the due as it stood then.
362	     */
363	    java.util.Optional<DueThen> dueThen(String sheetId, long claimId, LocalDate on) {
364	        return claims.findByIdAndSheetId(claimId, sheetId).map(claim -> new DueThen(on,
365	                dueNow(sheetId, claim, people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null))));
366	    }
367	
368	    /**
369	     * Settle a claim as {@link #move(String, String, long, ClaimStatus, String)} does, freezing the due it had
370	     * as of a past day of the sheet in place of today's.
371	     */
372	    @Transactional
373	    public long settleAsOf(String sheetId, String user, long claimId, DueThen then) {
374	        return move(sheetId, user, claimId, ClaimStatus.SETTLED, null, true, then);
375	    }
376	
377	    /** Move a claim; a settle with a due as of a past day freezes that due in place of today's. */
378	    private long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason,
379	            boolean judgeHere, DueThen then) {
380	        Claim claim = claim(sheetId, claimId);
381	        if (!claim.getStatus().canBecome(next)) {
382	            throw new ResponseStatusException(HttpStatus.CONFLICT,
383	                    "A " + claim.getStatus() + " claim cannot become " + next);
384	        }
385	        Permission permission = switch (next) {
386	            case OPEN -> Permission.OPEN;
387	            case SETTLED -> Permission.SETTLE;
388	            case VOID -> Permission.VOID;
389	            default -> null;
390	        };
391	        if (permission != null && !access.allows(sheetId, user, permission)) {
392	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
393	                    "Your role may not " + permission.action() + " a claim on this sheet");
394	        }
395	        String reasonGiven = next == ClaimStatus.VOID ? voidReasons.require(sheetId, voidReason) : null;
396	        String reversed = null;
397	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
398	            requireVoidableSettled(sheetId, user, claim);
399	            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
400	        }
401	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
402	            throw new ResponseStatusException(HttpStatus.CONFLICT,
403	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
404	        }
405	        if (judgeHere && next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
406	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
407	                    "The user who opened a claim cannot settle it");
408	        }
409	        if (judgeHere && next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
410	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
411	                    "The user who last edited a claim cannot settle it");
412	        }
413	        if (next == ClaimStatus.OPEN) {
414	            requireUnflagged(sheetId, user, claim);
415	            requireNote(sheetId, claim);
416	            requireUnderCap(sheetId, claim);
417	            requireUnderMaxOpen(sheetId, claim);
418	        }
419	        Rollup.Figures before = rollup.figures(sheetId);
420	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
421	        if (next == ClaimStatus.OPEN && needsReview(sheetId, claim, owner)) {
422	            next = ClaimStatus.REVIEW;
423	        }
424	        if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) {
425	            claim.setOpenedBy(user);
426	        }
427	        if (next == ClaimStatus.REVIEW) {
428	            claim.setReviewOn(sheets.today(sheetId));
429	        }
430	        String due = null;
431	        if (next == ClaimStatus.SETTLED) {
432	            BigDecimal fixed = then == null ? dueNow(sheetId, claim, owner) : then.due();
433	            if (judgeHere) {
434	                requireProof(sheetId, claim, owner, fixed);
435	            }
436	            String grade = owner == null ? null : owner.gradeOn(sheets.today(sheetId));
437	            if (access.canSettle(sheetId, user, grade, claim.getDate(), fixed)) {
438	                claim.setSettledDue(fixed);
439	                numberIfNone(sheetId, claim);
440	                due = fixed == null ? "n/a" : fixed.toPlainString();
441	            } else {
442	                next = ClaimStatus.PENDING;
443	                claim.setPendingOn(sheets.today(sheetId));
444	            }
445	        }
446	        String number = claim.getShownNumber();
447	        claim.setStatus(next);
448	        if (next == ClaimStatus.VOID) {
449	            claim.setVoidReason(reasonGiven);
450	        }
451	        log(sheetId, user, claim, owner);
452	        claims.flush();
453	        String person = owner == null ? "" : owner.getName();
454	        String event = switch (next) {
455	            case OPEN -> "CLAIM_OPENED";
456	            case REVIEW -> "CLAIM_REVIEW";
457	            case PENDING -> "CLAIM_PENDING";
458	            case SETTLED -> "CLAIM_SETTLED";
459	            case VOID -> "CLAIM_VOIDED";
460	            case DRAFT, DELETED -> throw new IllegalStateException();
461	        };
462	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
463	                due, null, reversed, null, null, reasonGiven,
464	                then != null && next == ClaimStatus.SETTLED ? then.on() : null));
465	        if (next == ClaimStatus.SETTLED) {
466	            watches.notifyWatchers(sheetId, user, owner, number);
467	        }
468	        rollup.changed(sheetId, user, before);
469	        return claim.getPersonId();
470	    }
