472	    /** Whether a claim being opened goes to REVIEW: its due (null: n/a) is above the review threshold in force on its date. */
473	    private boolean needsReview(String sheetId, Claim claim, Person owner) {
474	        BigDecimal threshold = sheets.settings(sheetId).reviewThreshold(claim.getDate());
475	        if (threshold == null) {
476	            return false;
477	        }
478	        BigDecimal due = dueNow(sheetId, claim, owner);
479	        return due != null && due.compareTo(threshold) > 0;
480	    }
