694	    /**
695	     * Part-settle an OPEN claim: split the amount off it as {@link #split} does, then settle the new claim
696	     * at once as the user, as settling does (PENDING when the clerk limit says so). The four-eyes rules and
697	     * the proof rule are judged on the claim split, before it is split; a split or a settle that would be
698	     * refused refuses the whole and nothing changes. Returns the person it belongs to.
699	     */
700	    @Transactional
701	    public long settlePart(String sheetId, String user, long claimId, BigDecimal amount) {
702	        Claim claim = claim(sheetId, claimId);
703	        if (user.equals(claim.getOpenedBy())) {
704	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
705	        }
706	        if (user.equals(claim.getEditedBy())) {
707	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
708	                    "The user who last edited a claim cannot settle it");
709	        }
710	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
711	        requireProof(sheetId, claim, owner, dueNow(sheetId, claim, owner));
712	        Claim part = splitOff(sheetId, user, claimId, amount);
713	        return move(sheetId, user, part.getId(), ClaimStatus.SETTLED, null, false);
714	    }
