716	    /** Split an amount off a claim as {@link #split} does, returning the new claim. */
717	    private Claim splitOff(String sheetId, String user, long claimId, BigDecimal amount) {
718	        Claim claim = claim(sheetId, claimId);
719	        if (claim.getStatus() != ClaimStatus.OPEN) {
720	            throw new ResponseStatusException(HttpStatus.CONFLICT,
721	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
722	        }
723	        if (Dues.deferred(claim, sheets.today(sheetId))) {
724	            throw new ResponseStatusException(HttpStatus.CONFLICT,
725	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
726	        }
727	        if (!access.allows(sheetId, user, Permission.OPEN)) {
728	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
729	        }
730	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
731	            throw new ResponseStatusException(HttpStatus.CONFLICT,
732	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
733	        }
734	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
735	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
736	        Rollup.Figures before = rollup.figures(sheetId);
737	        claim.setAmount(claim.getAmount().subtract(amount));
738	        claim.unbind();
739	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
740	        sheets.load(sheetId, user);
741	        LocalDate created = sheets.today(sheetId);
742	        int terms = sheets.settings(sheetId).termsFor(owner.termsOn(created), owner.gradeOn(created), created);
743	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
744	        part.setTerms(terms);
745	        part.setSplitFrom(claim.getShownNumber());
746	        part.setTags(claim.getTags());
747	        part.setLateEntry(claim.isLateEntry());
748	        part.setOpenedBy(user);
749	        part.setStatus(ClaimStatus.OPEN);
750	        log(sheetId, user, part, owner);
751	        claims.saveAndFlush(part);
752	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
753	                claim.getShownNumber(), part.getShownNumber()));
754	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
755	                part.getDate(), part.getShownNumber(), null));
756	        rollup.changed(sheetId, user, before);
757	        return part;
758	    }
