888	    /**
889	     * Remind an OPEN or PENDING claim: it takes the sheet's today as its reminded date. A claim can be
890	     * reminded once per sheet's today; a claim in any other status, or one already reminded on the sheet's
891	     * today, is refused and nothing changes. A reminder changes no figure, so a claim due by a date inside a
892	     * closed period can still be reminded. When the sheet has an escalation gap and the claim's previous
893	     * reminder was at least that many days before the sheet's today, the claim is escalated too (once per
894	     * claim ever). Returns the person it belongs to.
895	     */
896	    @Transactional
897	    public long remind(String sheetId, String user, long claimId) {
898	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
899	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
900	        if (!claim.getStatus().unpaid()) {
901	            throw new ResponseStatusException(HttpStatus.CONFLICT,
902	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
903	        }
904	        LocalDate today = sheets.today(sheetId);
905	        if (today.equals(claim.getRemindedOn())) {
906	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today (" + today + ")");
907	        }
908	        LocalDate previous = claim.getRemindedOn();
909	        Integer gap = sheets.settings(sheetId).escalateAfter();
910	        boolean escalate = gap != null && previous != null && !claim.isEscalated()
911	                && !previous.plusDays(gap).isAfter(today);
912	        claim.setRemindedOn(today);
913	        if (escalate) {
914	            claim.setEscalated(true);
915	        }
916	        claims.flush();
917	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
918	        events.publishEvent(new ClaimReminded(sheetId, user, person, claim.getAmount(), claim.getDate(),
919	                claim.getShownNumber()));
920	        if (escalate) {
