1022	    public long resettle(String sheetId, String user, long claimId) {
1023	        Claim claim = claim(sheetId, claimId);
1024	        if (claim.getStatus() != ClaimStatus.SETTLED) {
1025	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1026	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can");
1027	        }
1028	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
1029	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-settle a claim");
1030	        }
1031	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
1032	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
1033	        Rollup.Figures before = rollup.figures(sheetId);
1034	        BigDecimal old = claim.getSettledDue();
1035	        BigDecimal fixed = Dues.asOpen(claim, owner::gradeOn, rates.table(sheetId));
1036	        claim.setSettledDue(fixed);
1037	        claim.logStatus(user, sheets.today(sheetId), fixed);
1038	        claims.flush();
1039	        events.publishEvent(new ClaimResettled(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
1040	                claim.getShownNumber(), old, fixed));
1041	        watches.notifyWatchers(sheetId, user, owner, claim.getShownNumber());
1042	        rollup.changed(sheetId, user, before);
1043	        return claim.getPersonId();
1044	    }
