1046	    /**
1047	     * Reject a PENDING claim with a reason, putting it back to OPEN (still bound by the last statement if
1048	     * that statement counted it). Only a steward or the person's approver rejects; a claim not PENDING or due by a date inside a closed
1049	     * period is refused and nothing changes. Returns the person it belongs to.
1050	     */
1051	    @Transactional
1052	    public long reject(String sheetId, String user, long claimId, String reason) {
1053	        Claim claim = pending(sheetId, user, claimId, "reject", "rejected");
1054	        Rollup.Figures before = rollup.figures(sheetId);
1055	        claim.setStatus(ClaimStatus.OPEN);
1056	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
1057	        log(sheetId, user, claim, owner);
1058	        claims.flush();
1059	        String person = owner == null ? "" : owner.getName();
1060	        events.publishEvent(new ClaimChanged("CLAIM_REJECTED", sheetId, user, person, claim.getAmount(),
1061	                claim.getDate(), claim.getShownNumber(), null, reason));
1062	        rollup.changed(sheetId, user, before);
1063	        return claim.getPersonId();
1064	    }
