1079	    /**
1080	     * As {@link #reassign(String, String, long, long)}; when {@code sameAllowed}, a claim already the new
1081	     * person's is moved to them again (listed as their newest claim) rather than refused, as a bulk move does.
1082	     */
1083	    @Transactional
1084	    public long[] reassign(String sheetId, String user, long claimId, long toPersonId, boolean sameAllowed) {
1085	        Claim claim = claim(sheetId, claimId);
1086	        if (!access.allows(sheetId, user, Permission.REASSIGN)) {
1087	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Your role may not reassign a claim on this sheet");
1088	        }
1089	        if (claim.getStatus() != ClaimStatus.DRAFT && claim.getStatus() != ClaimStatus.OPEN
1090	                && claim.getStatus() != ClaimStatus.PENDING) {
1091	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1092	                    "A " + claim.getStatus() + " claim cannot be reassigned");
1093	        }
1094	        if (claim.isCorrection()) {
1095	            throw new ResponseStatusException(HttpStatus.CONFLICT,
1096	                    "A correction belongs with the claim it corrects and cannot be reassigned");
1097	        }
1098	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
1099	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
1100	        Person to = people.findByIdAndSheetId(toPersonId, sheetId)
1101	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "Choose a person on the sheet"));
1102	        if (!sameAllowed && from.getId().equals(to.getId())) {
1103	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s");
1104	        }
1105	        requireNotRetired(to, claim.getDate());
1106	        Rollup.Figures before = rollup.figures(sheetId);
1107	        claim.setPersonId(to.getId());
1108	        claim.unbind();
1109	        renumber(sheetId, claim);
1110	        claims.flush();
1111	        claims.relist(claim.getId());
1112	        events.publishEvent(new ClaimReassigned(sheetId, user, to.getName(), claim.getAmount(), claim.getDate(),
1113	                claim.getShownNumber(), from.getName(), to.getName()));
1114	        rollup.changed(sheetId, user, before);
1115	        return new long[] { from.getId(), to.getId() };
1116	    }
