1118	    /**
1119	     * Share a claim with another person on the sheet, who then holds the percent given (two decimals, more than
1120	     * 0.00) of its due. The claim's own person, a person already holding a share of it, shares totalling more
1121	     * than 100.00, or a SETTLED, VOID or DELETED claim is refused and nothing changes. Returns the claim's own
1122	     * person and each holder of a share, the new one last.
1123	     */
1124	    @Transactional
1125	    public List<Long> share(String sheetId, String user, long claimId, long withPersonId, BigDecimal share) {
1126	        if (share.scale() > 2 || share.compareTo(BigDecimal.ZERO) <= 0) {
1127	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A share is a percent with two decimals, more than 0.00");
1128	        }
1129	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
1130	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
1131	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID
1132	                || claim.getStatus() == ClaimStatus.DELETED) {
