135	   183	                    grade.on(rates.today()), person.termsOn(rates.today()), person.getContact(), Tags.list(person.getTags()), claims.stream().map(c -> ClaimView.of(c, grade, rates, held)).toList(), money(claimed),
136	   184	                    money(Dues.total(grade, claims, rates, held, parts, cut)), money(Dues.excess(grade, claims, rates, held, parts, cut)),
137	   185	                    statements.count(),
138	   186	                    money(statements.lastDueTotal()), statements.lastDate(), person.isRetired(),
139	   187	                    person.getRetiredFrom(), person.isHeld(),
140	   188	                    person.getHolds().stream().map(h -> new HoldView(h.getFromDate(), h.getToDate())).toList(),
141	   189	                    overdue.size(), money(Dues.sum(grade, overdue, rates)),
142	   190	                    patrons, Dues.active(claims, held, rates.today()),
143	   191	                    money(Dues.recentSettled(claims, rates.today())), person.retiredOn(rates.today()),
144	   192	                    money(Dues.aged(grade, claims, rates, held, 0, 30)),
145	   193	                    money(Dues.aged(grade, claims, rates, held, 31, 60)),
146	   194	                    money(Dues.aged(grade, claims, rates, held, 61, Long.MAX_VALUE)),
147	   195	                    money(Dues.settledTotal(grade, claims, rates, held, parts)),
148	   196	                    money(Dues.openTotal(grade, claims, rates, held, parts)), person.getAliases(), clashing,
149	   197	                    person.getOrigin(), person.getRetirements().stream()
150	   198	                            .map(r -> new RetirementView(r.getFromDate(), r.getToDate())).toList(),
151	   199	                    snapshots.stream().map(s -> new SnapshotView(s.getDay(), s.getDueTotal())).toList(),
152	   200	                    statements.lines().stream()
153	   201	                            .map(l -> new StatementLineView(l.date(), l.dueTotal() == null ? "n/a" : money(l.dueTotal())))
154	   202	                            .toList(),
