159	   207	        /**
160	   208	         * One line per dated thing about the person, in date order, and on a date their grade changes, then
161	   209	         * claims, then holds, then retirements, then unretirements (lines of a kind in text order):
162	   210	         * {@code <date> grade <grade>}, {@code <date> claim <amount> <status>}, {@code <date> hold [to <date>]},
163	   211	         * {@code <date> retired} and {@code <date> unretired}. The first grade (no from-date) has no line.
164	   212	         */
165	   213	        static List<String> timeline(Person person, List<Claim> claims) {
166	   214	            record Entry(LocalDate date, int kind, String text) {
167	   215	            }
168	   216	            List<Entry> entries = new ArrayList<>();
169	   217	            person.getGrades().stream().filter(g -> g.getFromDate() != null)
170	   218	                    .forEach(g -> entries.add(new Entry(g.getFromDate(), 0, "grade " + g.getGrade())));
171	   219	            claims.forEach(c -> entries.add(new Entry(c.getDate(), 1,
172	   220	                    "claim " + money(c.getAmount()) + " " + c.getStatus())));
173	   221	            person.getHolds().forEach(h -> entries.add(new Entry(h.getFromDate(), 2,
174	   222	                    h.getToDate() == null ? "hold" : "hold to " + h.getToDate())));
175	   223	            person.getRetirements().forEach(r -> {
176	   224	                entries.add(new Entry(r.getFromDate(), 3, "retired"));
177	   225	                entries.add(new Entry(r.getToDate(), 4, "unretired"));
178	   226	            });
179	   227	            if (person.getRetiredFrom() != null) {
180	   228	                entries.add(new Entry(person.getRetiredFrom(), 3, "retired"));
181	   229	            }
182	   230	            return entries.stream().filter(e -> e.date() != null)
183	   231	                    .sorted(Comparator.comparing(Entry::date).thenComparingInt(Entry::kind)
184	   232	                            .thenComparing(Entry::text))
185	   233	                    .map(e -> e.date() + " " + e.text()).toList();
186	   234	        }
