188	   236	        private static String band(BigDecimal score, RateTable rates) {
189	   237	            Integer mid = rates.settings().scoreMid();
190	   238	            Integer high = rates.settings().scoreHigh();
191	   239	            if (mid == null || high == null) {
192	   240	                return null;
193	   241	            }
194	   242	            return score.compareTo(BigDecimal.valueOf(high)) >= 0 ? "HIGH"
195	   243	                    : score.compareTo(BigDecimal.valueOf(mid)) >= 0 ? "MID" : "LOW";
196	   244	        }
197	   245	    }
