 67	        return claim.isCorrection() ? RateService.due(claim.getAmount(), rates.on(grade, claim.getDate(), claim.getId()),
 68	                rates.rounding(claim.getRoundsBy()))
 69	                : rates.figure(claim.getAmount(), grade, claim.getDate(), claim.getId());
 70	    }
 71	
 72	    /**
 73	     * The figure the claim would have today as an OPEN claim bound by no statement: its rate figure held up to
 74	     * the floor in force on its date, plus the late charge it has today on that floored figure (none once waived)
 75	     * when its due-by plus its grace has passed; a correction has neither floor nor late charge. Null when there is none. Re-settling a claim
 76	     * fixes its due at this figure.
 77	     */
 78	    public static BigDecimal asOpen(Claim claim, Grades grades, RateTable rates) {
 79	        BigDecimal base = rateFigure(claim, grades, rates);
 80	        if (base == null || claim.isCorrection()) {
 81	            return base;
 82	        }
 83	        LocalDate graceBy = graceBy(claim, grades, rates);
 84	        BigDecimal floored = rates.floored(base, claim.getDate());
 85	        return graceBy.isBefore(rates.today()) && !claim.isWaived()
 86	                ? floored.add(rates.lateCharge(floored, graceBy, claim.getRoundsBy()))
 87	                : floored;
 88	    }
 89	
 90	    /** Whether a statement binds the claim's figure: it is stated (whatever its status, PENDING included). */
 91	    public static boolean bound(Claim claim) {
 92	        return claim.isStated();
 93	    }
 94	
 95	    /**
 96	     * Whether the claim is late in review: REVIEW, with the sheet's review SLA set, and its review day (the
 97	     * sheet's today when it went to REVIEW) plus the SLA days before the sheet's today.
 98	     */
 99	    public static boolean reviewLate(Claim claim, RateTable rates) {
100	        Integer sla = rates.settings().reviewSla();
101	        return claim.getStatus() == ClaimStatus.REVIEW && sla != null && claim.getReviewOn() != null
102	                && claim.getReviewOn().plusDays(sla).isBefore(rates.today());
103	    }
104	
105	    /**
106	     * Whether the claim is late pending: PENDING, with the sheet's pending SLA set, and its pending day (the
107	     * sheet's today when it last went to PENDING) plus the SLA days before the sheet's today.
108	     */
109	    public static boolean pendingLate(Claim claim, RateTable rates) {
110	        Integer sla = rates.settings().pendingSla();
111	        return claim.getStatus() == ClaimStatus.PENDING && sla != null && claim.getPendingOn() != null
112	                && claim.getPendingOn().plusDays(sla).isBefore(rates.today());
113	    }
114	
115	    /**
116	     * Whether the claim is overdue: OPEN or PENDING, not {@link #deferred deferred}, and due by a date before
117	     * the sheet's today (its due-by, fixed when it was added, plus its {@link #graceBy grace}).
118	     */
119	    public static boolean overdue(Claim claim, Grades grades, RateTable rates) {
120	        return claim.getStatus().unpaid() && !deferred(claim, rates.today())
121	                && graceBy(claim, grades, rates).isBefore(rates.today());
122	    }
123	
124	    /**
125	     * The date a claim's overdue and late charge count from: its due-by plus the grace days in force on its
126	     * date for its person's grade in force then (none: its due-by). The due-by shown is unchanged.
127	     */
128	    public static LocalDate graceBy(Claim claim, Grades grades, RateTable rates) {
129	        return claim.getDueBy().plusDays(rates.settings().grace(grades.on(claim.getDate()), claim.getDate()));
130	    }
131	
132	    /**
133	     * Whether the claim is deferred on the given today: deferred until a date after it and not
134	     * {@link #bound bound} by a statement, OPEN or (settled while a statement bound it) SETTLED. A deferral
135	     * takes effect only once the binding ends: while bound the claim stays in the totals and can be settled.
136	     */
137	    public static boolean deferred(Claim claim, LocalDate today) {
138	        return deferralPending(claim, today)
139	                && (claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED);
140	    }
141	
142	    /** Whether the claim is deferred until a date after the given today and no statement binds it, whatever its status. */
143	    public static boolean deferralPending(Claim claim, LocalDate today) {
144	        return !bound(claim) && claim.getDeferredUntil() != null && today.isBefore(claim.getDeferredUntil());
145	    }
146	
147	    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
148	    public static List<Claim> overdue(List<Claim> claims, Grades grades, RateTable rates, Holds holds) {
149	        return claims.stream().filter(c -> counts(c, holds, rates.today()) && overdue(c, grades, rates)).toList();
150	    }
151	
152	    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
153	    public static BigDecimal sum(Grades grades, List<Claim> claims, RateTable rates) {
154	        return claims.stream().map(c -> figure(c, grades, rates)).filter(Objects::nonNull)
155	                .reduce(BigDecimal.ZERO, BigDecimal::add);
156	    }
157	
158	    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
159	    private static boolean kept(Claim claim) {
160	        return claim.getSettledDue() != null || (bound(claim) && claim.getStatedDue() != null);
161	    }
162	
163	    /**
164	     * Whether the claim counts in the live totals on the sheet's today: OPEN, PENDING and SETTLED claims do,
165	     * held ones included, except that an OPEN or PENDING claim of a person whose retirement date that today has
166	     * reached counts in none, unless a statement binds it, and a claim {@link #deferred deferred} on that today counts in none.
167	     */
168	    public static boolean counts(Claim claim, Holds holds, LocalDate today) {
169	        return claim.getStatus().counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
170	    }
171	
172	    /**
173	     * A person's claimed: the sum of the amounts of the OPEN, PENDING and SETTLED claims, leaving out the claims
174	     * that correct another, a claim {@link #deferred deferred} on the sheet's today and an unbound OPEN or PENDING
175	     * claim once that today has reached the person's retirement date. A hold (the person's or the claim's own)
176	     * leaves a claim in claimed and in every total.
177	     */
178	    public static BigDecimal claimed(List<Claim> claims, Holds holds, LocalDate today) {
179	        return claims.stream().filter(c -> c.getCorrects() == null && c.getStatus().counts() && !deferred(c, today)
180	                && !retiredOut(c, holds, today)).map(Claim::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
181	    }
182	
183	    /** Whether the person's retirement leaves the claim out: unbound, OPEN or PENDING, and that today has reached it. */
184	    private static boolean retiredOut(Claim claim, Holds holds, LocalDate today) {
185	        return !bound(claim) && claim.getStatus().unpaid() && holds.retiredOn(today);
186	    }
187	
188	    /**
189	     * Whether the person's retirement leaves the claim out of the live totals (see {@link #retiredOut}). A hold
190	     * (the person's or the claim's own) leaves out none: it only takes the person's cut of a pool.
191	     */
192	    private static boolean leftOut(Claim claim, Holds holds, LocalDate today) {
193	        return retiredOut(claim, holds, today);
194	    }
195	
196	    /**
197	     * Whether the person is active on the sheet's today: they have an OPEN or PENDING claim that counts (see
198	     * {@link #counts}) dated within the 30 days up to and including that today.
199	     */
200	    public static boolean active(List<Claim> claims, Holds holds, LocalDate today) {
201	        LocalDate from = today.minusDays(29);
202	        return claims.stream().anyMatch(c -> (c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
203	                && counts(c, holds, today) && !c.getDate().isBefore(from) && !c.getDate().isAfter(today));
204	    }
205	
206	    /**
207	     * The sum of the due figures of the OPEN and PENDING claims that count (see {@link #counts}) whose age on
208	     * the sheet's today (the days from the claim's date; a claim dated after that today is aged 0) is from
209	     * {@code fromDays} to {@code toDays} inclusive (0.00 with none); a claim with no figure is skipped.
210	     */
211	    public static BigDecimal aged(Grades grades, List<Claim> claims, RateTable rates, Holds holds, long fromDays,
212	            long toDays) {
213	        LocalDate today = rates.today();
214	        return sum(grades, claims.stream().filter(c -> c.getStatus().unpaid() && counts(c, holds, today))
215	                .filter(c -> {
216	                    long age = Math.max(0, ChronoUnit.DAYS.between(c.getDate(), today));
217	                    return age >= fromDays && age <= toDays;
218	                }).toList(), rates);
219	    }
220	
221	    /**
222	     * The sum of the settled figures of the SETTLED claims dated within the 90 days up to and including the
223	     * sheet's today, each at the figure frozen when it was settled (0.00 with none); one with none is skipped.
224	     */
225	    public static BigDecimal recentSettled(List<Claim> claims, LocalDate today) {
226	        LocalDate from = today.minusDays(89);
227	        return claims.stream().filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null
228	                && !c.getDate().isBefore(from) && !c.getDate().isAfter(today)).map(Claim::getSettledDue)
229	                .reduce(BigDecimal.ZERO, BigDecimal::add);
230	    }
231	
232	    /**
233	     * The status the claim had at the end of the given day, as its status log records it (each line on the
234	     * sheet's today then); null when it was added after that day.
235	     */
236	    public static ClaimStatus statusAsOf(Claim claim, LocalDate day) {
237	        ClaimStatus status = null;
238	        for (ClaimLogLine line : claim.getLog()) {
239	            if (!line.getOn().isAfter(day)) {
240	                status = line.getStatus();
241	            }
242	        }
243	        return status;
244	    }
245	
246	    /**
247	     * Whether the claim counts in a period ending on {@code end}: its status at the end of that day (see
248	     * {@link #statusAsOf}) is OPEN, PENDING or SETTLED, and it is not deferred on the
249	     * sheet's today, as in {@link #counts}; so too by a retirement reached on that today.
250	     */
251	    public static boolean countsAsOf(Claim claim, Holds holds, LocalDate today, LocalDate end) {
252	        ClaimStatus then = statusAsOf(claim, end);
253	        return then != null && then.counts() && !deferred(claim, today) && !leftOut(claim, holds, today);
254	    }
255	
256	    /**
257	     * A person's due-total (see {@link #total}); a person not on hold.
258	     */
259	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates) {
260	        return total(grades, claims, rates, Holds.NONE);
261	    }
262	
263	    /**
264	     * The date whose cap holds a person's due-total: the date of their latest claim that counts (see
265	     * {@link #counts}); the sheet's today when none does.
266	     */
267	    public static LocalDate capOn(List<Claim> claims, RateTable rates, Holds holds) {
268	        return claims.stream().filter(c -> counts(c, holds, rates.today())).map(Claim::getDate)
269	                .max(Comparator.naturalOrder()).orElse(rates.today());
270	    }
271	
272	    /**
273	     * A person's due-total: their {@link #uncapped} sum held to the cap in force on {@link #capOn}, see {@link RateTable#capped}.
274	     * Null (n/a) when the sum is.
275	     */
276	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
277	        return rates.capped(uncapped(grades, claims, rates, holds), capOn(claims, rates, holds));
278	    }
279	
280	    /** What a person's {@link #uncapped} sum is above the sheet's cap: 0.00 when it is not, or is n/a. */
281	    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
282	        return rates.excess(uncapped(grades, claims, rates, holds), capOn(claims, rates, holds));
283	    }
284	
285	    /**
286	     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a)
287	     * when the grade in force on the sheet's today has no rate on it, unless a claim that counts has a
288	     * figure not made by that grade (kept, or at the rate for another grade in force on its date): then it
289	     * is the sum of the figures there are; so too when that grade's rate has ended by the sheet's today and
290	     * a claim that counts has a figure.
291	     */
292	    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
293	        List<Claim> counting = claims.stream().filter(c -> counts(c, holds, rates.today())).toList();
294	        String current = grades.on(rates.today());
295	        boolean ended = rates.ended(current, rates.today());
296	        boolean shown = rates.current(current) != null || counting.stream().anyMatch(c -> kept(c)
297	                || ((ended || !current.equals(grades.on(c.getDate()))) && figure(c, grades, rates) != null));
298	        return shown ? counting.stream().map(c -> figure(c, grades, rates))
299	                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
300	    }
301	
302	    /**
303	     * The settled part of a person's {@link #uncapped} sum: the due figures of their SETTLED claims that count,
304	     * each at its frozen figure (corrections included); a claim with no figure is skipped.
305	     */
306	    public static BigDecimal settledTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
307	        return part(grades, claims, rates, holds, true);
308	    }
309	
310	    /**
311	     * The open part of a person's {@link #uncapped} sum: the due figures of their OPEN and PENDING claims that
312	     * count (a deferred or retired-and-left-out claim does not); a claim with no figure is skipped.
313	     */
314	    public static BigDecimal openTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
315	        return part(grades, claims, rates, holds, false);
316	    }
317	
318	    /**
319	     * A person's score: their {@link #settledTotal settled figures}, leaving out corrections (only SETTLED
320	     * claims that correct nothing count), divided by 100, minus 5 for every
321	     * {@link #overdue overdue claim that counts}, rounded half to even to a whole number.
322	     */
323	    public static BigDecimal score(Grades grades, List<Claim> claims, RateTable rates, Holds holds) {
324	        List<Claim> uncorrecting = claims.stream().filter(c -> c.getCorrects() == null).toList();
325	        return settledTotal(grades, uncorrecting, rates, holds).movePointLeft(2)
326	                .subtract(BigDecimal.valueOf(5L * overdue(claims, grades, rates, holds).size()))
327	                .setScale(0, RoundingMode.HALF_EVEN);
328	    }
329	
330	    /**
331	     * A person's parts of shared claims that count, net: what their settled and open figures gain as a holder and
332	     * give up as the claim's own person, and whether they hold a part of any such claim.
333	     */
334	    public record Parts(BigDecimal settled, BigDecimal open, boolean holder) {
335	
336	        public static final Parts NONE = new Parts(BigDecimal.ZERO, BigDecimal.ZERO, false);
337	
338	        /** The settled and open parts added up. */
339	        public BigDecimal total() {
340	            return settled.add(open);
341	        }
342	
343	        Parts plus(BigDecimal part, boolean settledPart, boolean holding) {
344	            return new Parts(settledPart ? settled.add(part) : settled, settledPart ? open : open.add(part),
345	                    holder || holding);
346	        }
347	    }
348	
349	    /**
350	     * A holder's part of a shared claim: the claim's due times their share divided by 100, rounded half to even to
351	     * two decimals.
352	     */
353	    public static BigDecimal part(BigDecimal due, BigDecimal share) {
354	        return due.multiply(share).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
355	    }
356	
357	    /**
358	     * A holder's part of an unsettled shared claim: the claim's amount times their share divided by 100, times the
359	     * rate of the holder's own grade in force on the claim's date divided by 100, rounded like the claim's figure;
360	     * null when that grade has no rate then.
361	     */
362	    public static BigDecimal part(Claim claim, BigDecimal share, Grades holder, RateTable rates) {
363	        BigDecimal pct = rates.on(holder.on(claim.getDate()), claim.getDate(), claim.getId());
364	        return RateService.due(claim.getAmount().multiply(share).movePointLeft(2), pct,
365	                rates.rounding(claim.isCorrection() ? claim.getRoundsBy() : claim.getDate()));
366	    }
367	
368	    /**
369	     * Everyone's {@link Parts} by person id: each shared claim that counts (see {@link #counts}, by its own person's
370	     * holds) and has a due figure (by its own person's grades) gives each holder their part and takes the same from
371	     * its own person, as a settled part when it is SETTLED, else as an open part. An unsettled claim's part is
372	     * worked out per holder (see {@link #part(Claim, BigDecimal, Grades, RateTable)}; 0.00 when their grade has no
373	     * rate, and then it does not make them a holder); a SETTLED claim keeps its parts as frozen, its settled due
374	     * times each share (see {@link #part(BigDecimal, BigDecimal)}). A claim of a person not given (null grades or
375	     * holds) is skipped.
376	     */
377	    public static Map<Long, Parts> parts(Collection<Claim> claims, Function<Long, Grades> grades,
378	            Function<Long, Holds> holds, RateTable rates) {
379	        Map<Long, Parts> parts = new HashMap<>();
380	        for (Claim claim : claims) {
381	            if (claim.getShares().isEmpty()) {
382	                continue;
383	            }
384	            Grades owner = grades.apply(claim.getPersonId());
385	            Holds held = holds.apply(claim.getPersonId());
386	            if (owner == null || held == null || !counts(claim, held, rates.today())) {
387	                continue;
388	            }
389	            BigDecimal due = figure(claim, owner, rates);
390	            if (due == null) {
391	                continue;
392	            }
393	            boolean settled = claim.getStatus() == ClaimStatus.SETTLED;
394	            for (ClaimShare share : claim.getShares()) {
395	                Grades holder = grades.apply(share.getPersonId());
396	                BigDecimal part = settled ? part(due, share.getShare())
397	                        : holder == null ? null : part(claim, share.getShare(), holder, rates);
398	                boolean holding = part != null;
399	                BigDecimal counted = holding ? part : BigDecimal.ZERO.setScale(2);
400	                parts.merge(share.getPersonId(), Parts.NONE.plus(counted, settled, holding),
401	                        (a, b) -> a.plus(b.total(), settled, b.holder()));
402	                parts.merge(claim.getPersonId(), Parts.NONE.plus(counted.negate(), settled, false),
403	                        (a, b) -> a.plus(b.total(), settled, false));
404	            }
405	        }
406	        return parts;
407	    }
408	
409	    /** A person's due-total (see {@link #total}) with their {@link Parts} of shared claims. */
410	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts) {
411	        return rates.capped(uncapped(grades, claims, rates, holds, parts), capOn(claims, rates, holds));
412	    }
413	
414	    /** What a person's {@link #uncapped} sum with their {@link Parts} is above the sheet's cap. */
415	    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts) {
416	        return rates.excess(uncapped(grades, claims, rates, holds, parts), capOn(claims, rates, holds));
417	    }
418	
419	    /**
420	     * A person's due-total (see {@link #total}) with their {@link Parts} of shared claims, held to the sheet's cap
421	     * less their cut total (see {@link RateTable#capped(BigDecimal, BigDecimal)}).
422	     */
423	    public static BigDecimal total(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts,
424	            BigDecimal cut) {
425	        return rates.capped(uncapped(grades, claims, rates, holds, parts), cut, capOn(claims, rates, holds));
426	    }
427	
428	    /** What a person's {@link #uncapped} sum with their {@link Parts} plus their cut total is above the sheet's cap. */
429	    public static BigDecimal excess(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts,
430	            BigDecimal cut) {
431	        return rates.excess(uncapped(grades, claims, rates, holds, parts), cut, capOn(claims, rates, holds));
432	    }
433	
434	    /**
435	     * A person's {@link #uncapped} sum plus their {@link Parts} of shared claims; a holder of a part has a sum
436	     * (0.00 for their own claims) even when their own would be n/a.
437	     */
438	    public static BigDecimal uncapped(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts) {
439	        BigDecimal own = uncapped(grades, claims, rates, holds);
440	        if (own == null && !parts.holder()) {
441	            return null;
442	        }
443	        return (own == null ? BigDecimal.ZERO : own).add(parts.total());
444	    }
445	
446	    /** A person's {@link #settledTotal} with the settled part of their {@link Parts}. */
447	    public static BigDecimal settledTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts) {
448	        return settledTotal(grades, claims, rates, holds).add(parts.settled());
449	    }
450	
451	    /** A person's {@link #openTotal} with the open part of their {@link Parts}. */
452	    public static BigDecimal openTotal(Grades grades, List<Claim> claims, RateTable rates, Holds holds, Parts parts) {
453	        return openTotal(grades, claims, rates, holds).add(parts.open());
454	    }
455	
456	    private static BigDecimal part(Grades grades, List<Claim> claims, RateTable rates, Holds holds, boolean settled) {
457	        return sum(grades, claims.stream().filter(c -> counts(c, holds, rates.today())
458	                && (c.getStatus() == ClaimStatus.SETTLED) == settled).toList(), rates);
459	    }
460	}

