  1	package net.officefloor.hq.app.claim;
  2	
  3	import jakarta.persistence.CollectionTable;
  4	import jakarta.persistence.Column;
  5	import jakarta.persistence.ElementCollection;
  6	import jakarta.persistence.Entity;
  7	import jakarta.persistence.EnumType;
  8	import jakarta.persistence.Enumerated;
  9	import jakarta.persistence.GeneratedValue;
 10	import jakarta.persistence.GenerationType;
 11	import jakarta.persistence.FetchType;
 12	import jakarta.persistence.Id;
 13	import jakarta.persistence.JoinColumn;
 14	import jakarta.persistence.OrderColumn;
 15	import jakarta.persistence.Table;
 16	import java.math.BigDecimal;
 17	import java.time.LocalDate;
 18	import java.util.ArrayList;
 19	import java.util.List;
 20	
 21	/**
 22	 * A claim a person makes: an amount (two decimals), a date, a note and a status. A negative amount is a
 23	 * correction, naming the number of the SETTLED claim of the same person it corrects.
 24	 */
 25	@Entity
 26	@Table(name = "claim")
 27	public class Claim {
 28	
 29	    @Id
 30	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 31	    private Long id;
 32	
 33	    @Column(name = "sheet_id", nullable = false)
 34	    private String sheetId;
 35	
 36	    @Column(name = "person_id", nullable = false)
 37	    private Long personId;
 38	
 39	    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
 40	    private BigDecimal amount;
 41	
 42	    @Column(name = "claim_date", nullable = false)
 43	    private LocalDate date;
 44	
 45	    @Column(name = "note", nullable = false)
 46	    private String note;
 47	
 48	    @Enumerated(EnumType.STRING)
 49	    @Column(name = "status", nullable = false)
 50	    private ClaimStatus status = ClaimStatus.DRAFT;
 51	
 52	    /** The number the claim got when settled or approved (or, before, when opened); null until then; a voided claim keeps it. */
 53	    @Column(name = "claim_number")
 54	    private Integer number;
 55	
 56	    /** The fiscal year (FY<year>) a sheet-wide number counts in, shown <FY>-<n>; null for a number given before. */
 57	    @Column(name = "fiscal_year")
 58	    private String fiscalYear;
 59	
 60	    /** The sequence a period-numbered claim counts in ('P<period id>', or 'X' for no period); null otherwise. */
 61	    @Column(name = "period_sequence")
 62	    private String periodSequence;
 63	
 64	    /** The claim's place in its period sequence; null for a sheet-wide number. */
 65	    @Column(name = "period_seq_number")
 66	    private Integer periodSeqNumber;
 67	
 68	    /** The number as shown for a period-numbered claim (<period name>-<n>, or X-<n>); null otherwise. */
 69	    @Column(name = "period_number")
 70	    private String periodNumber;
 71	
 72	    /** The user who opened the claim; null while a draft and once voided. */
 73	    @Column(name = "opened_by")
 74	    private String openedBy;
 75	
 76	    /** The bulk settle batch that settled the claim (to SETTLED or PENDING); null when settled one at a time or never. */
 77	    @Column(name = "settle_batch")
 78	    private Integer settleBatch;
 79	
 80	    /** The user who last edited the claim; null while never edited. */
 81	    @Column(name = "edited_by")
 82	    private String editedBy;
