682	/**
683	 * A claim's status: it starts as DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling
684	 * one above the clerk limit leaves it PENDING until a steward approves it (SETTLED) or rejects it (back to
685	 * OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID), and a
686	 * steward may void a SETTLED one within 7 days of its settlement. A DRAFT can be DELETED, and restored to a DRAFT on
687	 * the sheet's today it was deleted. A claim whose due is above the sheet's review threshold goes to REVIEW
688	 * instead of OPEN when opened, until a steward reviews it (OPEN); a REVIEW claim can be voided. Only OPEN,
689	 * PENDING and SETTLED claims count toward what is claimed.
690	 */
691	public enum ClaimStatus {
692	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
693	
694	    /** Whether the claim counts toward claimed, due-total and every total. */
695	    public boolean counts() {
696	        return this == OPEN || this == PENDING || this == SETTLED;
697	    }
698	
699	    /** Whether the claim is still to be paid: OPEN or PENDING. */
700	    public boolean unpaid() {
701	        return this == OPEN || this == PENDING;
702	    }
703	
704	    /**
705	     * Whether a claim in this status may be moved to the given one by opening, settling or voiding it; a
706	     * PENDING claim leaves PENDING only by being approved, rejected or voided, and a REVIEW claim REVIEW only
707	     * by being reviewed or voided.
708	     */
709	    public boolean canBecome(ClaimStatus next) {
710	        return switch (next) {
711	            case OPEN -> this == DRAFT;
712	            case PENDING, SETTLED -> this == OPEN;
713	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
714	            case DRAFT, DELETED, REVIEW -> false;
715	        };
716	    }
717	}
