  4	/** A figure as the server sends it: digits, a dot, two decimals. */
  5	const FIGURE = /^(-?)(\d+)\.(\d{2})$/;
  6	
  7	/**
  8	 * Shows a figure (an amount, total, rate, share or cut with two decimals) in the signed-in user's locale:
  9	 * under de as 1.234,56, under en as it comes. Anything that is not such a figure is shown as it is.
 10	 * Impure, as it reads the user's locale, which may change while the value does not.
 11	 */
 12	@Pipe({ name: 'figure', pure: false })
 13	export class FigurePipe implements PipeTransform {
 14	  private readonly session = inject(Session);
 15	
 16	  transform<T>(value: T): T | string {
 17	    return formatFigure(value, this.session.locale());
 18	  }
 19	}
 20	
 21	export function formatFigure<T>(value: T, locale: string): T | string {
 22	  if (locale !== 'de' || typeof value !== 'string') return value;
 23	  const m = FIGURE.exec(value);
 24	  if (!m) return value;
 25	  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+$)/g, '.')},${m[3]}`;
 26	}
