 34	/**
 35	 * Names the date the screen shows the sheet as of (X-As-Of) on every sheet request while one is set; otherwise
 36	 * names the screen's preview date (X-Preview) on every sheet read while one is set. Changes are never previewed.
 37	 */
 38	export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
 39	  const session = inject(Session);
 40	  const asOf = session.asOf();
 41	  if (req.context.get(LIVE) || !req.url.startsWith('/api/sheets/')) return next(req);
 42	  if (asOf !== null) return next(req.clone({ setHeaders: { 'X-As-Of': asOf } }));
 43	  const preview = session.preview();
 44	  if (preview === null || req.method !== 'GET') return next(req);
 45	  return next(req.clone({ setHeaders: { 'X-Preview': preview } }));
 46	};
