170	    const res = await firstValueFrom(
171	      this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null, {
172	        headers: { 'X-User': this.user() ?? '' },
173	      }),
174	    );
175	    if (this.sheet() === res.id) this.archived.set(res.archived);
176	  }
177	
178	  /** Clone the active sheet to another id, which must never have been used. */
