183	    /**
184	     * Delegate the steward role to a user name from a from-date to a to-date, inclusive. Only a steward by
185	     * the role set (not by a delegation) may delegate, and the to-date may not be before the from-date.
186	     */
187	    @Transactional
188	    public Delegation delegate(String sheetId, String user, String name, LocalDate from, LocalDate to) {
189	        sheets.load(sheetId, user);
190	        if (roleSet(sheetId, user) != Role.STEWARD) {
191	            throw new DelegationRefused("Only a steward can delegate the steward role");
192	        }
193	        if (to.isBefore(from)) {
194	            throw new DelegationRefused("The to-date is before the from-date");
195	        }
196	        Delegation row = delegations.saveAndFlush(new Delegation(sheetId, name, from, to, user));
197	        events.publishEvent(new Delegated(sheetId, user, name, from, to));
198	        return row;
199	    }
