283	    /**
284	     * Save the settings given, as written (blank: none, or the default), in one change; a setting left
285	     * out (null) is kept as it is. A dated one is saved from its from-date.
286	     */
287	    @Transactional
288	    public void setSettings(String sheetId, String user, Dated clerkLimit, Dated floor, Dated terms,
289	            Map<String, Dated> gradeTerms, Dated latePct, String policyDate, String periodNumberingFrom, String graceDays,
290	            Map<String, Dated> gradeGrace, Dated cap, Dated proofThreshold, Dated noteThreshold, Map<Permission, String> permissions, String entryDate,
291	            Map<String, Dated> gradeProofThreshold, String pot, String parent, String fiscalStartMonth,
292	            String alertThreshold, Dated rounding, Dated reviewThreshold, String escalateAfter, String reviewSla, String pendingSla, String proofKinds,
293	            String defaultGrade, Map<String, Dated> gradeClerkLimit, String scoreMid, String scoreHigh,
294	            String scoreLog, String maxOpen) {
295	        if (scoreLog != null && !scoreLog.isEmpty() && !scoreLog.equals("on")) {
296	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The score log is on or blank");
297	        }
298	        if (defaultGrade != null && !defaultGrade.isEmpty()
299	                && !GradeService.grades(addedGrades, sheetId).contains(defaultGrade)) {
300	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The default grade is one of the sheet's grades");
301	        }
302	        if (fiscalStartMonth != null && !fiscalStartMonth.isEmpty()
303	                && (Integer.parseInt(fiscalStartMonth) < 1 || Integer.parseInt(fiscalStartMonth) > 12)) {
304	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The fiscal year start month is 1 to 12");
305	        }
306	        if (rounding != null && !rounding.value().isEmpty() && DatedSettings.roundingMode(rounding.value()) == null) {
307	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rounding mode is half-up or half-even");
308	        }
309	        if (clerkLimit != null) {
310	            setDated(sheetId, user, CLERK_LIMIT, money(clerkLimit.value(), null), clerkLimit.from(), false);
311	        }
312	        gradeClerkLimit.forEach((grade, limit) -> {
313	            if (limit != null) {
314	                setDated(sheetId, user, DatedSettings.gradeClerkLimitKey(grade), money(limit.value(), null), limit.from(), false);
315	            }
316	        });
317	        if (floor != null) {
318	            setDated(sheetId, user, FLOOR, money(floor.value(), Sheet.DEFAULT_FLOOR), floor.from(), true);
319	        }
320	        if (terms != null) {
321	            setDated(sheetId, user, TERMS, days(terms.value(), Sheet.DEFAULT_TERMS), terms.from(), false);
322	        }
323	        gradeTerms.forEach((grade, days) -> {
324	            if (days != null) {
325	                setDated(sheetId, user, gradeTermsKey(grade), days(days.value(), null), days.from(), false);
326	            }
327	        });
328	        if (latePct != null) {
329	            setDated(sheetId, user, LATE_PCT, money(latePct.value(), Sheet.DEFAULT_LATE_PCT), latePct.from(), true);
330	        }
331	        if (rounding != null) {
332	            setDated(sheetId, user, ROUNDING, rounding.value().isEmpty() ? null : rounding.value(), rounding.from(), true);
333	        }
334	        if (policyDate != null) {
335	            setPolicyDate(sheetId, user, policyDate.isEmpty() ? null : LocalDate.parse(policyDate));
336	        }
337	        if (periodNumberingFrom != null) {
338	            setPeriodNumberingFrom(sheetId, user,
339	                    periodNumberingFrom.isEmpty() ? null : LocalDate.parse(periodNumberingFrom));
340	        }
341	        if (graceDays != null) {
342	            setGraceDays(sheetId, user, graceDays.isEmpty() ? null : Integer.valueOf(graceDays));
343	        }
344	        gradeGrace.forEach((grade, days) -> {
345	            if (days != null) {
346	                setDated(sheetId, user, gradeGraceKey(grade), days(days.value(), null), days.from(), true);
347	            }
348	        });
349	        if (cap != null) {
350	            setDated(sheetId, user, CAP, money(cap.value(), null), cap.from(), true);
351	        }
352	        if (proofThreshold != null) {
353	            setDated(sheetId, user, PROOF_THRESHOLD, money(proofThreshold.value(), null), proofThreshold.from(), false);
354	        }
355	        gradeProofThreshold.forEach((grade, threshold) -> {
356	            if (threshold != null) {
357	                setDated(sheetId, user, gradeProofThresholdKey(grade), money(threshold.value(), null), threshold.from(), false);
358	            }
359	        });
360	        if (noteThreshold != null) {
361	            setDated(sheetId, user, NOTE_THRESHOLD, money(noteThreshold.value(), null), noteThreshold.from(), false);
362	        }
363	        if (reviewThreshold != null) {
364	            setDated(sheetId, user, REVIEW_THRESHOLD, money(reviewThreshold.value(), null), reviewThreshold.from(), false);
365	        }
366	        permissions.forEach((permission, roles) -> {
367	            if (roles != null) {
368	                setPermission(sheetId, user, permission, roles.trim());
369	            }
370	        });
371	        if (entryDate != null) {
372	            setEntryDate(sheetId, user, entryDate.isEmpty() ? null : LocalDate.parse(entryDate));
373	        }
374	        if (pot != null) {
375	            setPot(sheetId, user, money(pot, null));
376	        }
377	        if (alertThreshold != null) {
378	            setAlertThreshold(sheetId, user, money(alertThreshold, null));
379	        }
380	        if (escalateAfter != null) {
381	            setEscalateAfter(sheetId, user, days(escalateAfter, null));
382	        }
383	        if (reviewSla != null) {
384	            setReviewSla(sheetId, user, days(reviewSla, null));
385	        }
386	        if (pendingSla != null) {
387	            setPendingSla(sheetId, user, days(pendingSla, null));
388	        }
389	        if (proofKinds != null) {
390	            setProofKinds(sheetId, user, proofKinds);
391	        }
392	        if (scoreLog != null) {
393	            setUndated(sheetId, user, SCORE_LOG, scoreLog.isEmpty() ? null : scoreLog);
394	        }
395	        if (scoreMid != null) {
396	            setUndated(sheetId, user, SCORE_MID, whole(scoreMid));
397	        }
398	        if (scoreHigh != null) {
399	            setUndated(sheetId, user, SCORE_HIGH, whole(scoreHigh));
400	        }
401	        if (maxOpen != null) {
402	            setUndated(sheetId, user, MAX_OPEN, whole(maxOpen));
403	        }
404	        if (defaultGrade != null) {
405	            setUndated(sheetId, user, DEFAULT_GRADE, defaultGrade.isEmpty() ? null : defaultGrade);
406	        }
407	        if (parent != null) {
408	            setParent(sheetId, user, parent.isEmpty() ? null : parent);
409	        }
410	        if (fiscalStartMonth != null) {
411	            setFiscalStartMonth(sheetId, user, fiscalStartMonth.isEmpty()
412	                    ? DatedSettings.DEFAULT_FISCAL_START_MONTH : Integer.parseInt(fiscalStartMonth));
413	        }
414	    }
