504	    /** Record an undated setting as written (null: none), replacing the one it had. */
505	    private void setUndated(String sheetId, String user, String key, String value) {
506	        sheets.load(sheetId, user);
507	        SheetSetting row = settingRows.findBySheetIdAndKeyAndFromDate(sheetId, key, null).orElse(null);
508	        if (row == null) {
509	            settingRows.saveAndFlush(new SheetSetting(sheetId, key, null, value));
510	        } else {
