517	    /**
518	     * Name the sheet's parent sheet (null: none), whose rates a grade with none in force on this sheet takes.
519	     * Not dated: the value holds from the beginning of time, replacing the one it had. Refused (409, changing
520	     * nothing) when it is this sheet, a sheet never loaded, or a sheet that has this sheet as an ancestor.
521	     */
522	    @Transactional
523	    public void setParent(String sheetId, String user, String parent) {
524	        sheets.load(sheetId, user);
525	        if (parent != null) {
526	            if (parent.equals(sheetId)) {
527	                throw new ResponseStatusException(HttpStatus.CONFLICT, "A sheet cannot be its own parent");
528	            }
529	            if (sheetRows.findById(parent).isEmpty()) {
530	                throw new ResponseStatusException(HttpStatus.CONFLICT, "No such sheet " + parent);
531	            }
532	            Set<String> seen = new HashSet<>();
533	            for (String up = parent; up != null && seen.add(up); up = sheets.settings(up).parent()) {
534	                if (up.equals(sheetId)) {
535	                    throw new ResponseStatusException(HttpStatus.CONFLICT, "The sheet is an ancestor of " + parent);
536	                }
537	            }
538	        }
539	        Rollup.Figures before = rollup.figures(sheetId);
540	        SheetSetting row = settingRows.findBySheetIdAndKeyAndFromDate(sheetId, PARENT, null).orElse(null);
541	        if (row == null) {
542	            settingRows.saveAndFlush(new SheetSetting(sheetId, PARENT, null, parent));
543	        } else {
544	            row.setValue(parent);
545	            settingRows.flush();
546	        }
547	        events.publishEvent(new SettingChanged(sheetId, user, PARENT, parent == null ? "" : parent, null));
548	        rollup.changed(sheetId, user, before);
549	    }
