572	    /** A figure as kept: two decimals; blank is the starting value given (null: none). */
573	    private static String money(String value, BigDecimal start) {
574	        BigDecimal figure = value.isEmpty() ? start : new BigDecimal(value).setScale(2, RoundingMode.HALF_UP);
575	        return figure == null ? null : figure.toPlainString();
