592	     * floor, the late percent, the cap), every figure it moves is announced. The terms fix the due-by of a
593	     * claim when it is added; a claim already added keeps the due-by it has. A change to a policy setting (see
594	     * {@link DatedSettings#POLICY}) is the sheet's next policy version, from the same date.
595	     */
596	    @Transactional
597	    public void setDated(String sheetId, String user, String key, String value, LocalDate from, boolean moves) {
598	        Sheet sheet = sheets.load(sheetId, user);
599	        LocalDate on = from == null ? sheet.getToday() : from;
600	        Rollup.Figures before = moves ? rollup.figures(sheetId) : null;
601	        SheetSetting row = settingRows.findBySheetIdAndKeyAndFromDate(sheetId, key, on).orElse(null);
602	        if (row == null) {
603	            settingRows.saveAndFlush(new SheetSetting(sheetId, key, on, value));
604	        } else {
605	            row.setValue(value);
606	            settingRows.flush();
607	        }
608	        if (DatedSettings.POLICY.contains(key)) {
609	            sheetRows.lockById(sheetId);
610	            versions.saveAndFlush(new PolicyVersion(sheetId, (int) versions.countBySheetId(sheetId) + 1, key, on, value));
611	        }
612	        events.publishEvent(new SettingChanged(sheetId, user, key, value == null ? "" : value, from));
613	        if (moves) {
614	            rollup.changed(sheetId, user, before);
615	        }
616	    }
617	
618	    /**
619	     * Save the sheet's policy date; null leaves it blank (the sheet's today). Every live figure rounds
620	     * by it; a settled or stated figure keeps the one it had.
621	     */
622	    @Transactional
623	    public LocalDate setPolicyDate(String sheetId, String user, LocalDate policyDate) {
624	        Sheet sheet = sheets.load(sheetId, user);
625	        Rollup.Figures before = rollup.figures(sheetId);
626	        sheet.setPolicyDate(policyDate);
627	        sheetRows.saveAndFlush(sheet);
628	        events.publishEvent(new SettingChanged(sheetId, user, POLICY_DATE, policyDate == null ? "" : policyDate.toString(), null));
629	        rollup.changed(sheetId, user, before);
630	        return policyDate;
631	    }
632	
633	    /**
