635	     * keep the numbers they have.
636	     */
637	    @Transactional
638	    public LocalDate setPeriodNumberingFrom(String sheetId, String user, LocalDate from) {
639	        Sheet sheet = sheets.load(sheetId, user);
640	        sheet.setPeriodNumberingFrom(from);
641	        sheetRows.saveAndFlush(sheet);
642	        events.publishEvent(new SettingChanged(sheetId, user, PERIOD_NUMBERING_FROM, from == null ? "" : from.toString(), null));
643	        return from;
644	    }
645	
646	    /**
647	     * Save the sheet's entry date; null turns it off. Not dated; while set, a new claim given no date takes
648	     * it in place of the sheet's today. Claims already added keep the dates they have.
649	     */
650	    @Transactional
651	    public LocalDate setEntryDate(String sheetId, String user, LocalDate entryDate) {
652	        Sheet sheet = sheets.load(sheetId, user);
653	        sheet.setEntryDate(entryDate);
654	        sheetRows.saveAndFlush(sheet);
655	        events.publishEvent(new SettingChanged(sheetId, user, ENTRY_DATE, entryDate == null ? "" : entryDate.toString(), null));
656	        return entryDate;
657	    }
658	
659	    /**
660	     * Save the sheet's grace days; null turns them off. Not dated; it takes effect at the next change of
661	     * the sheet's today.
662	     */
663	    @Transactional
664	    public Integer setGraceDays(String sheetId, String user, Integer days) {
665	        Sheet sheet = sheets.load(sheetId, user);
666	        sheet.setGraceDays(days);
667	        sheetRows.saveAndFlush(sheet);
668	        events.publishEvent(new SettingChanged(sheetId, user, GRACE_DAYS, days == null ? "" : days.toString(), null));
669	        return days;
670	    }
671	
672	    /**
673	     * Whether the user may settle a claim of the given due outright: a steward settles anything, a clerk
674	     * a due up to the clerk limit in force on the claim's date: the claim's person's grade's then when one is
675	     * set, else the sheet's (a due of n/a, null, is within any limit). A clerk's settle above it
676	     * leaves the claim PENDING for a steward.
677	     */
678	    @Transactional(readOnly = true)
679	    public boolean canSettle(String sheetId, String user, String grade, LocalDate date, BigDecimal due) {
680	        if (due == null) {
681	            return true;
682	        }
683	        BigDecimal limit = sheets.settings(sheetId).clerkLimitFor(grade, date);
684	        return limit == null || due.compareTo(limit) <= 0 || !EnumSet.of(Role.CLERK, Role.RESTRICTED).contains(roleOf(sheetId, user));
685	    }
