 24	export function gradeDueCents(grades: readonly string[], people: PersonWithClaims[]): { grade: string; due: number }[] {
 25	  return gradesOf(grades, people).map((grade) => ({
 26	    grade,
 27	    due: people
 28	      .filter((p) => !p.retired && p.grade === grade)
 29	      .reduce((sum, p) => sum + (p.dueTotal === null ? 0 : cents(p.dueTotal)), 0),
 30	  }));
 31	}
