 33	/** How many claims the people have in each status, in status order. */
 34	export function statusCounts(people: PersonWithClaims[]): { status: string; count: number }[] {
 35	  const claims = people.flatMap((p) => p.claims);
 36	  return STATUSES.map((status) => ({ status, count: claims.filter((c) => c.status === status).length }));
