154	  protected readonly byGrade = computed(() =>
155	    gradesOf(this.grades.codes(), this.people()).map((grade) => {
156	      const on = this.people().filter((p) => !p.retired && p.grade === grade);
157	      const due = on.reduce((sum, p) => sum + (p.dueTotal === null ? 0 : cents(p.dueTotal)), 0);
158	      return { grade, count: on.length, dueTotal: (due / 100).toFixed(2), active: on.filter((p) => p.active).length };
159	    }),
