162	  protected readonly byPeriod = computed(() => {
163	    const totals = periodDueTotals(this.periods(), this.people());
164	    const previous = new Map<number, string>();
165	    const byStart = [...this.periods()].sort((a, b) => a.from.localeCompare(b.from));
166	    byStart.forEach((p, i) => {
167	      if (i > 0) previous.set(p.id, totals[byStart[i - 1].id]);
168	    });
169	    return this.periods().map((p) => {
170	      const before = previous.get(p.id);
171	      const change = before === undefined ? '' : ((cents(totals[p.id]) - cents(before)) / 100).toFixed(2);
172	      return { name: p.name, dueTotal: totals[p.id], change };
173	    });
174	  });
