180	      const month = c.date.slice(0, 7);
181	      const due = c.counts && c.due !== null ? cents(c.due) : 0;
182	      totals.set(month, (totals.get(month) ?? 0) + due);
183	    }
184	    return [...totals.keys()].sort().map((month) => ({ month, dueTotal: ((totals.get(month) ?? 0) / 100).toFixed(2) }));
185	  });
