   119	    /** Every row of the sheet as it stands now; null when it was never started. */
   120	    private Rows rows(String sheetId) {
   121	        List<Map<String, String>> sheet = select("SHEET", "id = ?", sheetId);
   122	        if (sheet.isEmpty()) {
