   131	
   132	    /**
   133	     * Run the read with the sheet shown as it stood at the end of the date, that date as its today; nothing
   134	     * the read does is kept. A sheet never started is read as it is.
   135	     */
   136	    public <T> T asOf(String sheetId, LocalDate date, Supplier<T> read) {
   137	        ReentrantLock lock = shown.computeIfAbsent(sheetId, k -> new ReentrantLock());
   138	        boolean within = lock.isHeldByCurrentThread();
   139	        lock.lock();
   140	        try {
   141	            return rolledBack.execute(status -> {
   142	                status.setRollbackOnly();
   143	                // within another as-of read (a pool's cuts at each period's end, in an as-of view) the sheet that
   144	                // read shows is put back afterwards, as the transaction they share is rolled back only at its end
   145	                Rows shownBefore = within ? rows(sheetId) : null;
   146	                put(sheetId, date);
   147	                T result = read.get();
   148	                if (shownBefore != null) {
   149	                    restore(sheetId, shownBefore);
   150	                }
