   158	    /**
   159	     * Run the read with the sheet's current records and the date as its today; nothing the read does is kept,
   160	     * and nothing a change of today does (snapshots, scores, closing) happens.
   161	     */
   162	    public <T> T preview(String sheetId, LocalDate date, Supplier<T> read) {
   163	        ReentrantLock lock = shown.computeIfAbsent(sheetId, k -> new ReentrantLock());
   164	        lock.lock();
   165	        try {
   166	            return rolledBack.execute(status -> {
   167	                status.setRollbackOnly();
