   169	                if (!jdbc.queryForList("SELECT today FROM sheet WHERE id = ? FOR UPDATE", LocalDate.class, sheetId)
   170	                        .isEmpty()) {
   171	                    jdbc.update("UPDATE sheet SET today = ? WHERE id = ?", date, sheetId);
   172	                }
   173	                return read.get();
   174	            });
