77	    if (c.due === null || retiredOut(c, person.retiredNow) || c.deferred) continue;
78	    const period = periodOf(periods, c.dueBy);
79	    if (!period || isFixed(period)) continue;
80	    const status = statusAsOf(c, period.to);
81	    if (status === 'OPEN' || status === 'PENDING' || status === 'SETTLED') totals[period.id] += cents(c.due);
82	  }
83	  const shown: Record<number, string> = {};
84	  for (const p of periods) {
85	    shown[p.id] = isFixed(p) ? (p.personTotals?.[person.id] ?? '0.00') : (totals[p.id] / 100).toFixed(2);
86	  }
87	  return shown;
