90	/** Per period id, the person's carried figure for it: the dues as shown now of their claims that count (the same
91	 * claims left out as personPeriodTotals) due by a date in a period ending before it starts and still OPEN or PENDING
92	 * at the end of its last day, by the status log, added up, with the opening balances pasted for them in it; or once closed or soft-closed the figure fixed then (0.00
93	 * for a person added later). */
94	export function personPeriodCarried(periods: Period[], person: PersonWithClaims): Record<number, string> {
95	  const totals: Record<number, number> = {};
96	  for (const p of periods) totals[p.id] = cents(p.personOpenings?.[person.id] ?? '0.00');
97	  for (const c of person.claims) {
98	    if (c.due === null || retiredOut(c, person.retiredNow) || c.deferred) continue;
99	    const home = periodOf(periods, c.dueBy);
100	    if (!home) continue;
101	    for (const p of periods) {
102	      if (home.to >= p.from) continue;
103	      const status = statusAsOf(c, p.to);
104	      if (status === 'OPEN' || status === 'PENDING') totals[p.id] += cents(c.due);
105	    }
106	  }
107	  const shown: Record<number, string> = {};
108	  for (const p of periods) {
109	    shown[p.id] = isFixed(p) ? (p.personCarried?.[person.id] ?? '0.00') : (totals[p.id] / 100).toFixed(2);
110	  }
111	  return shown;
112	}
