114	/** Per period id, its due-total: the people's due-totals for it, added up. */
115	export function periodDueTotals(periods: Period[], people: PersonWithClaims[]): Record<number, string> {
116	  const totals: Record<number, number> = {};
117	  for (const p of periods) totals[p.id] = 0;
118	  for (const person of people) {
119	    const figures = personPeriodTotals(periods, person);
120	    for (const p of periods) totals[p.id] += cents(figures[p.id]);
121	  }
122	  const shown: Record<number, string> = {};
123	  for (const p of periods) shown[p.id] = (totals[p.id] / 100).toFixed(2);
124	  return shown;
125	}
