127	/** Per period id, its classic due-total: the dues as shown now of the people's claims due by a date in it that count
128	 * (OPEN, PENDING or SETTLED) by their status now, added up, with the same claims left out as personPeriodTotals; or once
129	 * closed or soft-closed the figure fixed then. */
130	export function classicPeriodDueTotals(periods: Period[], people: PersonWithClaims[]): Record<number, string> {
131	  const totals: Record<number, number> = {};
132	  for (const p of periods) totals[p.id] = 0;
133	  for (const person of people) {
134	    for (const c of person.claims) {
135	      if (c.due === null || retiredOut(c, person.retiredNow) || c.deferred) continue;
136	      const period = periodOf(periods, c.dueBy);
137	      if (!period || isFixed(period)) continue;
138	      if (c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED') totals[period.id] += cents(c.due);
139	    }
140	  }
141	  const shown: Record<number, string> = {};
142	  for (const p of periods) shown[p.id] = isFixed(p) ? (p.closedTotal ?? '0.00') : (totals[p.id] / 100).toFixed(2);
143	  return shown;
144	}
