146	/** Per period id, how many of the people's claims are due by a date in it, VOID and DELETED claims left out. */
147	export function periodClaimCounts(periods: Period[], people: PersonWithClaims[]): Record<number, number> {
148	  const counts: Record<number, number> = {};
149	  for (const p of periods) counts[p.id] = 0;
150	  for (const person of people) {
151	    for (const c of person.claims) {
152	      if (c.status === 'VOID' || c.status === 'DELETED') continue;
153	      const period = periodOf(periods, c.dueBy);
154	      if (period) counts[period.id] += 1;
155	    }
156	  }
157	  return counts;
158	}
