596	  /** Post a generate and show the periods made and how many, or the refusal. */
597	  private async runGenerate(sheet: string, path: string, body: object): Promise<void> {
598	    const headers = { 'X-User': this.session.user() ?? '' };
599	    this.busy = true;
600	    try {
601	      const made = await firstValueFrom(
602	        this.http.post<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${path}`, body, { headers }),
603	      );
604	      if (this.session.sheet() !== sheet) return;
605	      const ids = new Set(made.map((p) => p.id));
606	      this.periods.update((ps) => [...ps.filter((p) => !ids.has(p.id)), ...made].sort((a, b) => a.from.localeCompare(b.from)));
607	      this.generated.set(made.length);
608	    } catch (err) {
609	      if (this.session.sheet() !== sheet) return;
610	      const message = err instanceof HttpErrorResponse && err.status === 409
611	        ? (err.error?.message ?? 'The periods could not be generated.')
612	        : 'Could not generate the periods.';
613	      this.genError.set(message);
614	    } finally {
615	      this.busy = false;
616	    }
617	  }
618	
619	  /**
620	   * Close a period, fixing its due-total, soft-close it, fixing its figures while its claims can still change,
621	   * reopen a closed or soft-closed one (a steward only, and not while locked), making it live again, or lock or
622	   * unlock it (a steward only); a refusal is shown on its row.
623	   */
624	  protected async act(p: Period, action: 'close' | 'soft-close' | 'reopen' | 'lock' | 'unlock'): Promise<void> {
625	    if (this.busy) return;
626	    this.rowError.set(null);
627	    const sheet = this.session.sheet();
628	    if (!sheet) return;
629	    const headers = { 'X-User': this.session.user() ?? '' };
630	    this.busy = true;
631	    try {
632	      const saved = await firstValueFrom(
633	        this.http.post<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${p.id}/${action}`, null, { headers }),
634	      );
635	      if (this.session.sheet() !== sheet) return;
636	      this.periods.update((ps) => ps.map((q) => (q.id === saved.id ? saved : q)));
637	    } catch (err) {
638	      if (this.session.sheet() !== sheet) return;
639	      const message = err instanceof HttpErrorResponse && err.status === 409
640	        ? (err.error?.message ?? REFUSED[action])
641	        : `Could not ${action} the period.`;
642	      this.rowError.set({ id: p.id, message });
643	    } finally {
644	      this.busy = false;
645	    }
646	  }
647	
648	  private async reload(sheet: string): Promise<void> {
649	    const loads = this.session.loads();
650	    const periods = await firstValueFrom(this.http.get<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`));
651	    if (this.session.sheet() === sheet && this.session.loads() === loads) this.periods.set(periods);
652	  }
653	}
