     1	package net.officefloor.hq.app.person;
    11	/**
    12	 * Who watches whom on a sheet: each user watches people of their own choosing, and every user watching a
    13	 * person is notified, in the order they started watching, when one of that person's claims is settled,
    14	 * approved or re-settled.
    15	 */
    16	@Service
    17	public class WatchService {
    19	    private final WatchRepository watches;
    20	    private final PersonRepository people;
    21	    private final SheetRepository sheetRows;
    22	    private final ApplicationEventPublisher events;
    24	    public WatchService(WatchRepository watches, PersonRepository people, SheetRepository sheetRows,
    25	            ApplicationEventPublisher events) {
    26	        this.watches = watches;
    27	        this.people = people;
    28	        this.sheetRows = sheetRows;
    29	        this.events = events;
    30	    }
    32	    /** The ids of the people the user watches on the sheet. */
    33	    @Transactional(readOnly = true)
    34	    public List<Long> watched(String sheetId, String user) {
    35	        return watches.findBySheetIdAndUserOrderByIdAsc(sheetId, user).stream().map(Watch::getPersonId).toList();
    36	    }
    38	    /**
    39	     * Start (on) or stop watching the person as the user. Starting to watch a person already watched, or
    40	     * stopping when not watching, is refused and nothing changes. Takes turns with other changes on the sheet.
    41	     */
    42	    @Transactional
    43	    public List<Long> watch(String sheetId, String user, long personId, boolean on) {
    44	        sheetRows.lockById(sheetId);
    45	        Person person = people.findByIdAndSheetId(personId, sheetId)
    46	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
    47	        var existing = watches.findByPersonIdAndUser(personId, user);
    48	        if (on == existing.isPresent()) {
    49	            throw new ResponseStatusException(HttpStatus.CONFLICT,
    50	                    on ? "Already watching " + person.getName() : "Not watching " + person.getName());
    51	        }
    52	        if (on) {
    53	            watches.saveAndFlush(new Watch(sheetId, personId, user));
    54	        } else {
    55	            watches.delete(existing.get());
    56	            watches.flush();
    57	        }
    58	        events.publishEvent(new PersonWatched(on ? "PERSON_WATCHED" : "PERSON_UNWATCHED", sheetId, user,
    59	                person.getName()));
    60	        return watched(sheetId, user);
    61	    }
    63	    /** Notify each user watching the person, in the order they started watching, of a change to their claim. */
    64	    public void notifyWatchers(String sheetId, String user, Person person, String number) {
    65	        if (person == null) {
    66	            return;
    67	        }
    68	        for (Watch w : watches.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, person.getId())) {
    69	            events.publishEvent(new WatcherNotified(sheetId, user, w.getUser(), person.getName(), number));
    70	        }
    71	    }
    72	}
