1	import { HttpClient, HttpErrorResponse } from '@angular/common/http';
2	import { Component, OnInit, computed, effect, inject, input, output, signal } from '@angular/core';
3	import { FigurePipe } from '../../core/figure';
4	import { firstValueFrom } from 'rxjs';
5	import { Session } from '../../core/session';
6	import { Period, periodOf } from '../periods/periods';
7	import { VoidReasonList } from '../void-reasons/void-reasons';
8	import { ClaimTemplateList } from '../claim-templates/claim-templates';
9	
10	/**
11	 * DRAFT when added, then OPEN, then SETTLED; a clerk's settle above the clerk limit leaves it PENDING
12	 * until a steward approves it (SETTLED) or rejects it (OPEN again). A steward can re-settle a SETTLED claim,
13	 * fixing its due again at today's figure. A DRAFT, OPEN or PENDING claim can be VOID,
14	 * as can a SETTLED one by a steward within 7 days of settling. A DRAFT can be DELETED (counting nowhere) and
15	 * restored to a DRAFT on the sheet's today it was deleted. A claim whose due is above the review threshold
16	 * goes to REVIEW when opened, counting in no total, until a steward reviews it (OPEN).
17	 */
18	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
19	
20	export type ClaimAction = 'open' | 'review' | 'settle' | 'approve' | 'reject' | 'resettle' | 'void' | 'delete' | 'restore';
21	
22	export interface Claim {
23	  id: number;
24	  amount: string;
25	  date: string;
26	  note: string;
27	  /** The amount at the rate for the person's grade, or once settled the due fixed then; null when there is no rate. */
28	  due: string | null;
29	  status: ClaimStatus;
30	  /** The number the claim got when settled or approved (or when opened, for a claim numbered before): the next on the sheet, or within its period (P1-1, X-1); null until then. */
31	  number: string | null;
32	  /** The user who opened the claim, kept once voided; null while it was never opened. */
33	  openedBy: string | null;
34	  /** Whether the person's last statement binds the claim to the figure it had then. */
35	  stated: boolean;
36	  /** Fixed when the claim was added: the terms-th business day after its date (no weekend or holiday on the sheet then). */
37	  dueBy: string;
38	  /** Whether the claim is OPEN or PENDING and its due-by is before the sheet's today. */
39	  overdue: boolean;
40	  /** For a correction (a negative amount), the number of the settled claim it corrects, as shown (3, P1-1); null otherwise. */
41	  corrects: string | null;
42	  /** The claim's status log, oldest first: one line per status it has had. */
43	  log: ClaimLogLine[];
44	  /** Whether the claim is OPEN and deferred until a date after the sheet's today: it then counts in no total,
45	   * is not overdue and cannot be settled. */
46	  deferred: boolean;
47	  /** The date the claim was last deferred until, kept once that date has passed; null when it was never deferred. */
48	  deferredUntil: string | null;
49	  /** How many proofs the claim has. */
50	  proofs: number;
51	  /** How many of its proofs are receipts. */
52	  proofsReceipt: number;
53	  /** How many of its proofs are photos. */
54	  proofsPhoto: number;
55	  /** For a claim split off another, the number of the claim it was split from, as shown; null otherwise. */
56	  splitFrom: string | null;
57	  /** The number of the bulk settle batch that settled the claim (to SETTLED or PENDING); null when settled one at a time or never. */
58	  settleBatch: number | null;
59	  /** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
60	  lockedBy: string | null;
61	  /** Whether the claim was added while its period was soft-closed. */
62	  lateEntry: boolean;
63	  /** Whether the claim is REVIEW and its review day plus the sheet's review SLA is before the sheet's today. */
64	  reviewLate: boolean;
65	  pendingLate: boolean;
66	  /** The number of the policy version in force on the claim's date: the versions from on or before it. */
67	  policy: number;
68	  /** Whether a steward waived the claim's late charge: it then bears none, whatever its overdue state. */
69	  waived: boolean;
70	  /** Whether the claim is held: it still counts in every total; a hold no longer leaves it out. */
71	  held: boolean;
72	  /** The other people the claim is shared with, in the order they were added: each holds a share (a percent with
73	   *  two decimals) of its due, which counts in their due-total, settled-total and open-total, and not in its own person's. */
74	  shares: ClaimShare[];
75	  /** The user a steward assigned the claim's review to; null when never assigned. It stays once the claim leaves REVIEW. */
76	  reviewAssigned: string | null;
77	  /** The last sheet's today a reminder was written for the claim; null when it was never reminded. */
78	  remindedOn: string | null;
79	  /** The claim's external reference, unique on the sheet without regard to case; null when it has none. */
80	  ref: string | null;
81	  /** The claim's tags: trimmed, lower-cased, without repeats, sorted. */
82	  tags: string[];
83	  /** The reason from the sheet's list the claim was voided with; null when it is not VOID or was voided without one. */
84	  voidReason: string | null;
85	  /** The claim's comments, oldest first. */
86	  comments: ClaimComment[];
87	  /** The claim's lines, in the order they were added; with any, its amount is theirs added up. */
88	  lines: ClaimLine[];
89	  /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED, and not left out by a retirement or a deferral (a hold leaves it counting). */
90	  counts: boolean;
91	}
92	
93	/** A share of a claim: the id of the person holding it and their percent with two decimals. */
94	export interface ClaimShare {
95	  personId: number;
96	  share: string;
97	}
98	
99	/** A line of a claim: its label, quantity (a whole number) and unit amount (two decimals). */
100	export interface ClaimLine {
101	  label: string;
102	  qty: number;
103	  unit: string;
104	}
105	
106	/** A comment on a claim: who wrote it, the sheet's today when it was written, and its text. */
107	export interface ClaimComment {
108	  by: string;
109	  on: string;
110	  text: string;
111	}
112	
113	/** A line of a claim's status log: the status, who changed it, the sheet's today then and its due then (null when none). */
114	export interface ClaimLogLine {
115	  status: ClaimStatus;
116	  by: string;
117	  on: string;
118	  due: string | null;
119	}
120	
121	/** A snapshot line of a person: the day being left and their due-total on it as shown ('n/a': none). */
122	export interface Snapshot {
123	  day: string;
124	  dueTotal: string;
125	}
126	
127	/** A statement line of a person: the statement's date and its due-total as shown ('n/a': none). */
128	export interface StatementLine {
129	  date: string;
130	  dueTotal: string;
131	}
132	
133	/** A past retirement of a person: from the date they were retired from to the day they were unretired. */
134	export interface Retirement {
135	  from: string;
136	  to: string;
137	}
138	
139	/** A hold on a person from a date to a date (both included); null to-date: open-ended. */
140	export interface Hold {
141	  from: string;
142	  to: string | null;
143	}
144	
145	/** Whether the claim is OPEN or PENDING, not bound by a statement, and its person's retirement date is reached
146	 * on the sheet's today: it then counts in no live total. */
147	export function retiredOut(c: Claim, retiredNow: boolean): boolean {
148	  return retiredNow && !c.stated && (c.status === 'OPEN' || c.status === 'PENDING');
149	}
150	
151	export interface PersonWithClaims {
152	  id: number;
153	  /** The version the person was last saved at; an edit sends the one its editor loaded. */
154	  version: number;
155	  name: string;
156	  grade: string;
157	  /** The person's own terms in days; null when they have none (their grade's or the sheet's apply). */
158	  terms: number | null;
159	  /** The person's contact, trimmed and lower-cased; null when they have none. */
160	  contact: string | null;
161	  /** The person's tags: trimmed, lower-cased, without repeats, sorted. */
162	  tags: string[];
163	  claims: Claim[];
164	  /** The amounts of the OPEN, PENDING and SETTLED claims added up, held ones included, but not deferred ones nor unbound ones left out by a retirement. */
165	  claimed: string;
166	  /** Claimed at the rate for the person's grade, held to the sheet's cap; null when the grade has no rate. */
167	  dueTotal: string | null;
168	  /** What the person's sum of figures is above the sheet's cap; 0.00 when it is not (or is n/a). */
169	  excess: string;
170	  /** How many statements were taken for the person. */
171	  statementCount: number;
172	  /** The last statement's due-total; null when there is none or it was n/a. */
173	  statedTotal: string | null;
174	  /** The sheet's today when the last statement was taken; null when there is none. */
175	  statementDate: string | null;
176	  /** Whether a retirement date is set: retired at once, whatever the date. */
177	  retired: boolean;
178	  /** The date the person is retired from; no claim dated after it can be added. Null when not retired. */
179	  retiredFrom: string | null;
180	  /** The person's past retirements, earliest first: no claim dated after the from and before the to of one can be added. */
181	  retirements: Retirement[];
182	  /** The person's snapshot lines, one per SNAPSHOT written for them, oldest first. */
183	  snapshots: Snapshot[];
184	  /** The person's statement lines, one per statement still standing, in the order taken. */
185	  statementLines: StatementLine[];
186	  /** Whether the person has any hold, whatever its dates. */
187	  held: boolean;
