    15	/**
    16	 * Import rates: lines of {@code grade,rate,from,to} (from and to may be left out or blank). Every line is first
    17	 * held to the rate form's rules, and the whole import is one change: a refused line sets nothing. Otherwise each
    18	 * line is set in order exactly as the rate form sets it, replacing a rate for the same grade and from-date.
    19	 */
    20	@Service
    21	public class RateImportService {
    22	
    23	    private static final Pattern PCT = Pattern.compile("\\d{1,12}(\\.\\d{1,2})?");
    24	
    25	    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    26	    }
    27	
    28	    private final RateService service;
    29	    private final SheetRepository sheetRows;
    30	    private final AddedGradeRepository added;
    31	
    32	    public RateImportService(RateService service, SheetRepository sheetRows, AddedGradeRepository added) {
    33	        this.service = service;
    34	        this.sheetRows = sheetRows;
    35	        this.added = added;
    36	    }
    37	
    38	    /** Set a rate per line, in order; returns how many were set. */
    39	    @Transactional
    40	    public int importRates(String sheetId, String user, String text) {
    41	        sheetRows.lockById(sheetId);
    42	        List<Line> lines = new ArrayList<>();
    43	        List<String> grades = GradeService.grades(added, sheetId);
    44	        for (String raw : text.split("\\R")) {
    45	            if (raw.isBlank()) continue;
    46	            lines.add(parse(raw, grades));
    47	        }
    48	        if (lines.isEmpty()) {
    49	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Paste at least one line");
    50	        }
    51	        for (Line line : lines) {
    52	            service.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct());
    53	        }
    54	        return lines.size();
    55	    }
    56	
    57	    private static Line parse(String raw, List<String> grades) {
    58	        String[] f = raw.split(",", -1);
    59	        if (f.length < 2 || f.length > 4) throw refused(raw, "give a grade, a rate, and optionally a from- and to-date");
    60	        String grade = f[0].trim();
    61	        if (!grades.contains(grade)) throw refused(raw, "the grade must be one of " + String.join(", ", grades));
    62	        String pct = f[1].trim();
    63	        if (!PCT.matcher(pct).matches()) throw refused(raw, "the rate must be 0.00 or more, with up to two decimals");
    64	        LocalDate from = f.length > 2 ? date(raw, f[2], "from-date") : null;
    65	        LocalDate to = f.length > 3 ? date(raw, f[3], "to-date") : null;
    66	        if (from != null && to != null && to.isBefore(from)) throw refused(raw, "the to-date is before the from-date");
    67	        return new Line(grade, new BigDecimal(pct), from, to);
    68	    }
    69	
    70	    private static LocalDate date(String raw, String field, String what) {
    71	        if (field.isBlank()) return null;
    72	        try {
    73	            return LocalDate.parse(field.trim());
    74	        } catch (DateTimeParseException e) {
    75	            throw refused(raw, "the " + what + " must be a date (yyyy-mm-dd)");
    76	        }
    77	    }
    78	
    79	    private static ResponseStatusException refused(String line, String why) {
    80	        return new ResponseStatusException(HttpStatus.CONFLICT, "Line \"" + line + "\": " + why);
    81	    }
    82	}
