   204	        Map<String, String> renumbered = new HashMap<>();
   205	        copies.stream().filter(oldNumbers::containsKey).sorted(Comparator.comparing(openedOn::get))
   206	                .forEach(claim -> {
   207	                    claimService.numberArrived(toSheet, claim);
   208	                    renumbered.put(oldNumbers.get(claim), claim.getShownNumber());
   209	                });
   210	        // a correction, or a claim split off another, names the claim it came from by its new number
   211	        for (Claim claim : copies) {
   212	            if (claim.getCorrects() != null) {
   213	                claim.setCorrects(renumbered.getOrDefault(claim.getCorrects(), claim.getCorrects()));
   214	            }
   215	            if (claim.getSplitFrom() != null) {
   216	                claim.setSplitFrom(renumbered.getOrDefault(claim.getSplitFrom(), claim.getSplitFrom()));
   217	            }
   218	        }
   219	        claims.flush();
