   221	        events.publishEvent(new SheetCloned(sheetId, user, toSheet, null));
   222	        events.publishEvent(new SheetCloned(toSheet, user, null, sheetId));
   223	        // the copy had no figures before: everyone and the totals count as moved
   224	        rollup.changed(toSheet, user, new Rollup.Figures(Map.of(), null));
   225	        return sheet;
   226	    }
