   162	    @Transactional
   163	    public void add(String sheetId, String user, long personId, BigDecimal amount, LocalDate start, Integer every,
   164	            Integer day, LocalDate end, String targetSheet) {
   165	        if ((every == null) == (day == null)) {
   166	            throw new PlanRefused("Enter either every how many days or a day of the month.");
   167	        }
   168	        if (every != null && every < 1) {
   169	            throw new PlanRefused("Enter a whole number of days, at least 1.");
   170	        }
   171	        if (day != null && (day < 1 || day > 31)) {
   172	            throw new PlanRefused("Enter a day of the month from 1 to 31.");
   173	        }
   174	        if (end.isBefore(start)) {
   175	            throw new PlanRefused("The end cannot be before the start.");
   176	        }
   177	        String target = targetSheet == null || targetSheet.isBlank() ? null : targetSheet.trim();
   178	        sheets.load(sheetId, user);
   179	        sheetRows.lockById(sheetId);
   180	        Person person = people.findByIdAndSheetId(personId, sheetId)
   181	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
   182	        if (target != null && !sheets.descendants(sheetId).contains(target)) {
   183	            throw new PlanRefused("The sheet " + target + " is not a descendant of this sheet.");
   184	        }
   185	        plans.saveAndFlush(new Plan(sheetId, personId, amount, start, every, day, end, target));
   186	        events.publishEvent(new PlanAdded(sheetId, user, person.getName(), amount, start, every, day, end, target));
   187	    }
   189	    /** Make the claims the plans are due up to the sheet's today; returns how many were made. */
   190	    public int generate(String sheetId, String user) {
   191	        sheets.load(sheetId, user);
   192	        if (access.isViewer(sheetId, user)) {
   193	            return 0;
   194	        }
   195	        LocalDate today = sheets.today(sheetId);
   196	        int count = 0;
   197	        for (Plan plan : list(sheetId)) {
   198	            LocalDate last = plan.getEnd().isBefore(today) ? plan.getEnd() : today;
   199	            List<PlanPause> skipped = pauses(plan);
   200	            String target = plan.getTargetSheetId() == null ? sheetId : plan.getTargetSheetId();
   201	            Long personId = plan.getTargetSheetId() == null ? plan.getPersonId() : namesake(sheetId, plan, target);
   202	            if (personId == null) {
   203	                continue; // no person of the plan's name on the sheet it names: nothing to make
   204	            }
   205	            for (LocalDate on : plan.datesUpTo(last)) {
   206	                if (skipped.stream().anyMatch(p -> p.skips(on))) {
   207	                    continue;
   208	                }
   209	                if (makeClaim(target, user, plan, personId, on)) {
   210	                    count++;
   211	                }
   212	            }
   213	        }
   214	        return count;
   215	    }
