   220	                .flatMap(p -> people.findBySheetIdOrderByPositionAscIdAsc(target).stream()
   221	                        .filter(t -> t.getName().trim().equalsIgnoreCase(p.getName().trim()))
   222	                        .map(Person::getId)
   223	                        .findFirst())
   224	                .orElse(null);
   225	    }
