   239	                        .getId();
   240	                made.saveAndFlush(new PlanClaim(plan.getId(), on, claimId));
   241	                return true;
   242	            }));
   243	        } catch (RuntimeException refused) {
   244	            return false; // refused by the claim form's rules: nothing written, tried again next time
