    50	    /**
    51	     * Add a holiday, fixing again the due-by of each claim not SETTLED or VOID due on or after it; refused when
    52	     * the date is already on the sheet's list.
    53	     */
    54	    @Transactional
    55	    public Holiday add(String sheetId, String user, LocalDate date) {
    56	        sheets.load(sheetId, user);
    57	        sheetRows.lockById(sheetId);
    58	        if (holidays.existsBySheetIdAndDay(sheetId, date)) {
    59	            throw new HolidayRefused("That date is already a holiday on this sheet.");
    60	        }
    61	        Rollup.Figures before = rollup.figures(sheetId);
    62	        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
    63	        Set<LocalDate> days = list(sheetId).stream().map(Holiday::getDay).collect(Collectors.toSet());
    64	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
    65	            if (claim.getStatus() != ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.VOID
    66	                    && !claim.isDueBySet() && !claim.getDueBy().isBefore(date)) {
    67	                claim.setDueBy(businessDaysAfter(claim.getDate(), claim.getTerms(), days));
    68	            }
    69	        }
    70	        claims.flush();
    71	        events.publishEvent(new HolidayAdded(sheetId, user, date));
    72	        rollup.changed(sheetId, user, before);
