    86	     */
    87	    public static LocalDate businessDaysAfter(LocalDate date, int terms, Set<LocalDate> holidays) {
    88	        LocalDate day = date;
    89	        for (int left = terms; left > 0; ) {
    90	            day = day.plusDays(1);
    91	            if (businessDay(day, holidays)) {
    92	                left--;
    93	            }
    94	        }
