    13	/**
    14	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
    15	 * so tests can assert side-effects by reading that file — the second test-assertion channel
    16	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
    17	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
    18	 *
    19	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
    20	 * SYNC) so a test reads the record immediately.
    21	 */
    22	@Service
    23	public class Audit {
    24	
    25	    private final Path file;
    26	
    27	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
    28	        this.file = Path.of(path);
    29	    }
    30	
    31	    /** Append one audit record. Tests assert the exact line(s) in the file. */
    32	    public synchronized void record(String entry) {
    33	        try {
    34	            Path parent = file.toAbsolutePath().getParent();
    35	            if (parent != null) {
    36	                Files.createDirectories(parent);
    37	            }
    38	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
    39	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
    40	        } catch (IOException e) {
    41	            throw new UncheckedIOException(e);
    42	        }
    43	    }
    44	
    45	    /** Every record the file holds, in file order (none while there is no file). */
    46	    public synchronized List<String> lines() {
    47	        try {
    48	            return Files.exists(file)
    49	                    ? Files.readAllLines(file, StandardCharsets.UTF_8).stream().filter(l -> !l.isEmpty()).toList()
    50	                    : List.of();
    51	        } catch (IOException e) {
    52	            throw new UncheckedIOException(e);
    53	        }
    54	    }
    55	
    56	    /** Truncate the audit file. */
    57	    public synchronized void clear() {
    58	        try {
    59	            Files.deleteIfExists(file);
    60	        } catch (IOException e) {
    61	            throw new UncheckedIOException(e);
    62	        }
    63	    }
    64	}

