 19	/**
 20	 * Terms count business days: every claim's due-by becomes the terms-th business day after its date, skipping
 21	 * weekends and the holidays on its sheet now. The terms a claim was fixed with are read back from its due-by:
 22	 * the days from its date to it, less the holidays it was moved past (the run of holidays just before it).
 23	 */
 24	@Component
 25	public class V53__business_day_due_by extends BaseJavaMigration {
 26	
 27	    @Override
 28	    public void migrate(Context context) throws SQLException {
 29	        Connection db = context.getConnection();
 30	        Map<String, Set<LocalDate>> holidays = new HashMap<>();
 31	        try (PreparedStatement select = db.prepareStatement("SELECT sheet_id, holiday_date FROM holiday");
 32	                ResultSet rows = select.executeQuery()) {
 33	            while (rows.next()) {
 34	                holidays.computeIfAbsent(rows.getString(1), k -> new HashSet<>()).add(rows.getDate(2).toLocalDate());
 35	            }
 36	        }
 37	        try (PreparedStatement select = db.prepareStatement("SELECT id, sheet_id, claim_date, due_by FROM claim");
 38	                PreparedStatement update = db.prepareStatement("UPDATE claim SET due_by = ? WHERE id = ?");
 39	                ResultSet rows = select.executeQuery()) {
 40	            while (rows.next()) {
 41	                Set<LocalDate> days = holidays.getOrDefault(rows.getString(2), Set.of());
 42	                LocalDate date = rows.getDate(3).toLocalDate();
 43	                LocalDate dueBy = rows.getDate(4).toLocalDate();
 44	                LocalDate unmoved = dueBy;
 45	                while (unmoved.isAfter(date) && days.contains(unmoved.minusDays(1))) {
 46	                    unmoved = unmoved.minusDays(1);
 47	                }
 48	                int terms = (int) Math.max(0, ChronoUnit.DAYS.between(date, unmoved));
 49	                update.setDate(1, Date.valueOf(HolidayService.businessDaysAfter(date, terms, days)));
 50	                update.setLong(2, rows.getLong(1));
 51	                update.executeUpdate();
 52	            }
 53	        }
 54	    }
 55	}
