127	/**
128	 * A steward merges a grade into another: the merge is recorded, then everyone whose grade in force on the
129	 * sheet's today is the merged grade is given the other from that today, in list order. Each person is edited
130	 * on their own, exactly as the person form would (their name and own terms kept, no version check), so one
131	 * that cannot be edited is left as they are while the rest go through. The merge is retroactive: once all are
132	 * done, every grade record of each person it moved that is the merged grade becomes the other, whatever its
133	 * date, and then the figures the merge as a whole moved are announced.
134	 */
135	@Service
136	public class GradeMergeService {
137	
138	    public record Result(int merged) {
139	    }
140	
141	    private final PersonService people;
142	    private final PersonRepository personRows;
143	    private final GradeService grades;
144	    private final SheetService sheets;
145	    private final Rollup rollup;
146	    private final TransactionTemplate tx;
147	
148	    public GradeMergeService(PersonService people, PersonRepository personRows, GradeService grades, SheetService sheets, Rollup rollup,
149	            TransactionTemplate tx) {
150	        this.rollup = rollup;
151	        this.tx = tx;
152	        this.people = people;
153	        this.personRows = personRows;
154	        this.grades = grades;
155	        this.sheets = sheets;
156	    }
157	
158	    public Result merge(String sheetId, String user, String from, String into) {
159	        Rollup.Figures before = tx.execute(status -> {
160	            grades.merged(sheetId, user, from, into);
161	            return rollup.figures(sheetId);
162	        });
163	        LocalDate today = sheets.today(sheetId);
164	        List<Long> moved = new ArrayList<>();
165	        for (Person p : people.list(sheetId)) {
166	            if (!from.equals(p.gradeOn(today))) {
167	                continue;
168	            }
169	            try {
170	                people.edit(sheetId, user, p.getId(), null, p.getName(), into, today, p.getTerms(), p.getContact());
171	                moved.add(p.getId());
172	            } catch (ResponseStatusException refused) {
173	                // refused: left as they are
174	            }
175	        }
176	        tx.executeWithoutResult(status -> {
177	            for (Long id : moved) {
178	                personRows.findByIdAndSheetId(id, sheetId).ifPresent(p -> p.regrade(from, into));
179	            }
180	            personRows.flush();
181	            rollup.changed(sheetId, user, before);
182	        });
183	        return new Result(moved.size());
184	    }
185	}
