203	/**
204	 * What a candidate rate for a grade would do to the dues shown: the OPEN and PENDING claims of people on that
205	 * grade (the grade in force on the claim's date) whose due would differ if the rate applied to the grade on
206	 * every date, and the sum of the differences. A claim bound by a statement keeps its due. Nothing is saved.
207	 */
208	@Service
209	public class RatePreviewService {
210	
211	    /** How many claims would show a different due, and the sum of new due minus current due. */
212	    public record Preview(int count, BigDecimal diff) {
213	    }
214	
215	    private final PersonRepository people;
216	    private final ClaimRepository claims;
217	    private final RateService rates;
218	
219	    public RatePreviewService(PersonRepository people, ClaimRepository claims, RateService rates) {
220	        this.people = people;
221	        this.claims = claims;
222	        this.rates = rates;
223	    }
224	
225	    @Transactional(readOnly = true)
226	    public Preview preview(String sheetId, String grade, BigDecimal pct) {
227	        RateTable table = rates.table(sheetId);
228	        List<Rate> candidate = new ArrayList<>(table.rates().stream().filter(r -> !r.getGrade().equals(grade)).toList());
229	        candidate.add(new Rate(sheetId, grade, null, null, pct.setScale(2, RoundingMode.HALF_UP)));
230	        RateTable then = new RateTable(candidate, table.today(), table.settings(), table.policyDate(),
231	                table.ancestors());
232	        Map<Long, List<Claim>> byPerson = claims.findBySheetIdOrderByIdDesc(sheetId).stream()
233	                .collect(Collectors.groupingBy(Claim::getPersonId));
234	        int count = 0;
235	        BigDecimal diff = BigDecimal.ZERO;
236	        for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
237	            for (Claim claim : byPerson.getOrDefault(person.getId(), List.of())) {
238	                if (!claim.getStatus().unpaid() || Dues.bound(claim) || !grade.equals(person.gradeOn(claim.getDate()))) {
239	                    continue;
240	                }
241	                BigDecimal now = Dues.figure(claim, person::gradeOn, table);
242	                BigDecimal next = Dues.figure(claim, person::gradeOn, then);
243	                if (!Objects.equals(now == null ? null : now.setScale(2, RoundingMode.HALF_UP),
244	                        next == null ? null : next.setScale(2, RoundingMode.HALF_UP))) {
245	                    count++;
246	                    diff = diff.add(next == null ? BigDecimal.ZERO : next).subtract(now == null ? BigDecimal.ZERO : now);
247	                }
248	            }
249	        }
250	        return new Preview(count, diff.setScale(2, RoundingMode.HALF_UP));
251	    }
252	}

