    19	@Component
    20	public class ViewerGuard implements HandlerInterceptor {
    21	
    22	    private static final String REFUSAL = "{\"message\":\"A viewer can change nothing.\"}";
    23	
    24	    private static final String ARCHIVED = "{\"message\":\"The sheet is archived: nothing on it can change.\"}";
    25	
    26	    private final AccessService access;
    27	
    28	    public ViewerGuard(AccessService access) {
    29	        this.access = access;
    30	    }
    31	
    32	    @Override
    33	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler)
    34	            throws Exception {
    35	        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
    36	            return true;
    37	        }
    38	        String path = request.getRequestURI();
    39	        if (path.endsWith("/load") || path.contains("/bulk-") || path.endsWith("/people/grade")
    40	                || path.endsWith("/people/retire") || path.endsWith("/people/hold")) {
    41	            return true;
    42	        }
    43	        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
    44	        String user = request.getHeader("X-User");
    45	        if (!(vars instanceof Map<?, ?> v) || user == null) {
    46	            return true;
    47	        }
    48	        Object sheet = v.containsKey("sheetId") ? v.get("sheetId") : v.get("id");
    49	        if (!(sheet instanceof String id)) {
    50	            return true;
    51	        }
    52	        String refusal = access.isArchived(id.trim()) ? ARCHIVED
    53	                : access.isViewer(id.trim(), user.trim()) ? REFUSAL : null;
    54	        if (refusal == null || (refusal == REFUSAL
    55	                && (path.endsWith("/plans/generate") || path.endsWith("/periods/generate")))) {
    56	            return true;
    57	        }
    58	        response.setStatus(HttpStatus.FORBIDDEN.value());
    59	        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
    60	        response.getWriter().write(refusal);
    61	        return false;
    62	    }
    63	}
